local cloneref = cloneref or function(o) return o end
local function svc(n)
    local ok, s = pcall(function() return cloneref(game:GetService(n)) end)
    if ok and s then return s end
    return game:GetService(n)
end

local Players      = svc("Players")
local RunService   = svc("RunService")
local UIS          = svc("UserInputService")
local TweenService = svc("TweenService")
local HttpService  = svc("HttpService")
local Workspace    = svc("Workspace")

local lp   = Players.LocalPlayer
local genv = (getgenv and getgenv()) or _G

if genv.AS_UNLOAD then pcall(genv.AS_UNLOAD) end

local BRAND_TITLE, BRAND_SUB = "AFRAID SIDE", "Made by @ipsi1an"
local VERSION = "1.0"

local conns = {}
local function bind(sig, fn)
    local c = sig:Connect(fn)
    conns[#conns + 1] = c
    return c
end

local function clamp(v, a, b) return math.max(a, math.min(b, v)) end
local function hsv(h, s, v) return Color3.fromHSV((h % 360) / 360, clamp(s, 0, 1), clamp(v, 0, 1)) end
local function rnd(a, b) return a + (b - a) * math.random() end
local function copyT(t) local r = {} for k, v in pairs(t) do r[k] = v end return r end
local function cam() return Workspace.CurrentCamera end
local function damp(k, dt) return 1 - math.exp(-k * dt) end
local function CK(t, c) return ColorSequenceKeypoint.new(t, c) end

local LOG = {}
local UI = {}
local function notify(text, dur) if UI.notify then return UI.notify(text, dur) end end
local lastReport = {}
local function report(tag, err)
    local msg = ("[%s] %s"):format(tag, tostring(err))
    LOG[#LOG + 1] = ("%.1f %s"):format(os.clock() % 100000, msg)
    if #LOG > 60 then table.remove(LOG, 1) end
    warn(msg)
    local t = os.clock()
    if not lastReport[tag] or t - lastReport[tag] > 8 then
        lastReport[tag] = t
        notify(msg:sub(1, 90), 4)
    end
end
local function try(tag, f, ...)
    local ok, e = pcall(f, ...)
    if not ok then report(tag, e) end
    return ok, e
end

