local ASSET_ORDER = {
    "logo", "glow", "spark", "dot", "ring", "petal", "flake", "heart",
    "star", "twinkle", "bg_sakura", "bg_eclipse", "bg_night", "ic_close", "ic_collapse", "ic_search",
    "ic_combat", "ic_visuals", "ic_movement", "ic_misc", "ic_settings",
}
local Assets = { tex = {}, ready = 0, total = #ASSET_ORDER, done = false, mode = "none", watchers = {} }
local FOLDER = "AfraidUI"
local TEX_VER = "v5"

local B64 = {}
do
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    for i = 1, 64 do B64[string.byte(chars, i)] = i - 1 end
end

local function b64decode(s)
    s = string.gsub(s, "[^%w%+/]", "")
    local out, n = {}, 0
    local len = #s
    local i = 1
    while i + 3 <= len do
        local a, b, c, d = string.byte(s, i, i + 3)
        local v = B64[a] * 262144 + B64[b] * 4096 + B64[c] * 64 + B64[d]
        n = n + 1
        out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
        i = i + 4
        if n % 5000 == 0 then task.wait() end
    end
    local rem = len - i + 1
    if rem == 3 then
        local a, b, c = string.byte(s, i, i + 2)
        local v = B64[a] * 262144 + B64[b] * 4096 + B64[c] * 64
        out[n + 1] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
    elseif rem == 2 then
        local a, b = string.byte(s, i, i + 1)
        local v = B64[a] * 262144 + B64[b] * 4096
        out[n + 1] = string.char(math.floor(v / 65536))
    end
    return table.concat(out)
end

local TEX_BUILTIN = { sparkle = "rbxasset://textures/particles/sparkles_main.dds" }
local TEX_FALLBACK = { glow = "sparkle", spark = "sparkle", dot = "sparkle", ring = "sparkle", twinkle = "sparkle", star = "sparkle", heart = "sparkle", petal = "sparkle", flake = "sparkle" }

local function TX(name)
    local t = Assets.tex[name]
    if t then return t end
    local fb = TEX_FALLBACK[name]
    return fb and TEX_BUILTIN[fb] or ""
end

function Assets.watchLogo(img)
    local function apply()
        local u = Assets.tex.logo
        if u and img and img.Parent then img.Image = u end
    end
    Assets.watchers[#Assets.watchers + 1] = apply
    apply()
end

function Assets.watchTex(img, name, prop)
    prop = prop or "Image"
    local function apply()
        local u = Assets.tex[name]
        if u and img and img.Parent ~= nil and img[prop] ~= u then img[prop] = u end
    end
    Assets.watchers[#Assets.watchers + 1] = apply
    apply()
end

local function fire()
    for _, f in ipairs(Assets.watchers) do pcall(f) end
end

function Assets.start()
    task.spawn(function()
        local ga = (type(getcustomasset) == "function" and getcustomasset) or (type(getsynasset) == "function" and getsynasset) or nil
        local fsOk = ga ~= nil and type(writefile) == "function" and type(readfile) == "function"
            and type(isfile) == "function" and type(isfolder) == "function" and type(makefolder) == "function"
        if fsOk then
            Assets.mode = "files"
            pcall(function() if not isfolder(FOLDER) then makefolder(FOLDER) end end)
            pcall(function() if not isfolder(FOLDER .. "/tex") then makefolder(FOLDER .. "/tex") end end)
        end
        for _, name in ipairs(ASSET_ORDER) do
            local entry = ASSET_DATA[name]
            local ok = false
            if fsOk and entry then
                local path = ("%s/tex/%s_%s.png"):format(FOLDER, name, TEX_VER)
                local valid = false
                pcall(function()
                    if isfile(path) then
                        local raw = readfile(path)
                        valid = (#raw == entry[1]) and (string.sub(raw, 2, 4) == "PNG")
                    end
                end)
                if not valid then
                    local okd, bin = pcall(b64decode, entry[2])
                    if okd and #bin == entry[1] then
                        local okw = pcall(writefile, path, bin)
                        valid = okw
                    end
                end
                if valid then
                    local o2, url = pcall(ga, path)
                    if o2 and type(url) == "string" and url ~= "" then
                        Assets.tex[name] = url
                        ok = true
                    end
                end
            end
            if ok then Assets.ready = Assets.ready + 1 end
            if ok and (name == "logo" or Assets.ready % 6 == 0) then fire() end
            task.wait()
        end
        Assets.done = true
        fire()
        dirty.ui = true
        if Assets.ready == 0 then
            notify("No file API in this executor: icons and logo are unavailable", 5)
        end
    end)
end
