local function seqFor(mode)
    if mode == "flow" then
        return ColorSequence.new({ CK(0, T.acc), CK(0.34, T.acc2), CK(0.67, T.acc3), CK(1, T.acc) })
    elseif mode == "rev" then
        return ColorSequence.new({ CK(0, T.acc3), CK(0.5, T.acc2), CK(1, T.acc) })
    elseif mode == "two" then
        return ColorSequence.new(T.acc, T.acc2)
    end
    return ColorSequence.new({ CK(0, T.acc), CK(0.5, T.acc2), CK(1, T.acc3) })
end

local themed, grads, renderersUI, glassL = {}, {}, {}, { win = {}, side = {}, sec = {} }
local function alive(inst)
    local ok, p = pcall(function() return inst.Parent end)
    return ok and p ~= nil
end
local function bindTheme(inst, prop, key)
    local l = themed[key]
    if not l then l = {}; themed[key] = l end
    l[#l + 1] = { inst, prop }
    inst[prop] = T[key]
    return inst
end
local function bindGrad(g, mode)
    grads[#grads + 1] = { g, mode or "lin" }
    g.Color = seqFor(mode)
    return g
end
local function reg(fn) renderersUI[#renderersUI + 1] = fn; return fn end
local function glassUse(kind, inst, base)
    local l = glassL[kind]
    l[#l + 1] = { inst, base or 0 }
end
UIX.bindTheme, UIX.bindGrad, UIX.reg, UIX.glassUse, UIX.alive = bindTheme, bindGrad, reg, glassUse, alive

local GLASS_MUL = { win = 0.55, side = 1, sec = 1 }
local function applyGlass()
    local g = clamp(tonumber(C("glass")) or 0, 0, 0.6)
    for kind, l in pairs(glassL) do
        for i = #l, 1, -1 do
            local e = l[i]
            if alive(e[1]) then
                e[1].BackgroundTransparency = clamp(e[2] + g * GLASS_MUL[kind], 0, 0.92)
            else
                table.remove(l, i)
            end
        end
    end
end
UIX.applyGlass = applyGlass

local function computePalette(dst)
    local th = THEMES[C("theme")] or THEMES.Afraid
    for k, v in pairs(th) do if typeof(v) == "Color3" then dst[k] = v end end
    dst.name = THEMES[C("theme")] and C("theme") or "Afraid"
    dst.theme = th
    if C("accentOn") then
        local h = tonumber(C("accentH")) or 262
        dst.acc = hsv(h, 0.58, 1)
        dst.acc2 = hsv(h + 40, 0.52, 1)
        dst.acc3 = hsv(h - 40, 0.6, 1)
        if th.light then dst.acc, dst.acc2, dst.acc3 = hsv(h, 0.72, 0.95), hsv(h + 40, 0.6, 1), hsv(h - 40, 0.7, 0.95) end
    end
    dst.light = th.light == true
    return dst
end
UIX.computePalette = computePalette

