local function pushTheme()
    for key, l in pairs(themed) do
        local c = T[key]
        for i = #l, 1, -1 do
            local e = l[i]
            if alive(e[1]) then e[1][e[2]] = c else table.remove(l, i) end
        end
    end
    for i = #grads, 1, -1 do
        local e = grads[i]
        if alive(e[1]) then e[1].Color = seqFor(e[2]) else table.remove(grads, i) end
    end
    for i = 1, #renderersUI do
        local ok, e = pcall(renderersUI[i], true)
        if not ok then report("ui-theme", e) end
    end
end
UIX.resolveTheme, UIX.pushTheme, UIX.seqFor = resolveTheme, pushTheme, seqFor

