local function icon(parent, name, size, key)
    local im = new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromOffset(size, size), Image = "", ScaleType = Enum.ScaleType.Fit, BorderSizePixel = 0 }, parent)
    bindTheme(im, "ImageColor3", key or "text")
    local short = (name:gsub("^ic_", ""))
    local PHM = { close = "x", collapse = "<", expand = ">", minus = "-", search = "o", menu = "=" }
    local ph = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = PHM[short] or "\u{2022}",
        TextSize = PHM[short] and math.floor(size * 0.8) or math.floor(size * 1.5), Font = F.bold, Visible = false, BorderSizePixel = 0 }, im)
    bindTheme(ph, "TextColor3", key or "text")
    local function apply()
        local u = Assets.tex[name]
        if u then
            if im.Image ~= u then im.Image = u end
            ph.Visible = false
        elseif Assets.done then
            ph.Visible = true
        end
    end
    Assets.watchers[#Assets.watchers + 1] = apply
    apply()
    return im
end
