local function chevron(parent, key, size)
    size = size or 12
    local f = new("Frame", { BackgroundTransparency = 1, Size = UDim2.fromOffset(size, size), AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0 }, parent)
    local half = size / 2
    local barLen = size * 0.62
    for _, side in ipairs({ -1, 1 }) do
        local b = new("Frame", { Size = UDim2.fromOffset(barLen, 2), AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0,
            Position = UDim2.fromOffset(half + side * size * 0.2, half - size * 0.06), Rotation = -side * 42 }, f)
        corner(b, 1)
        bindTheme(b, "BackgroundColor3", key or "dim")
    end
    return f
end
UIX.chevron = chevron

local function ripple(btn, pos, key)
    pcall(function()
        local sc = UIX.curScale and UIX.curScale() or 1
        local abs, sz = btn.AbsolutePosition, btn.AbsoluteSize
        local lx, ly = (pos.X - abs.X) / sc, (pos.Y - abs.Y) / sc
        if lx ~= lx or ly ~= ly or lx < 0 or ly < 0 or lx > sz.X / sc or ly > sz.Y / sc then lx, ly = sz.X / sc / 2, sz.Y / sc / 2 end
        local big = math.max(sz.X, sz.Y) / sc * 2.4
        local r = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(lx, ly), Size = UDim2.fromOffset(6, 6),
            BackgroundColor3 = T[key or "acc"], BackgroundTransparency = 0.7, BorderSizePixel = 0, ZIndex = 9 }, btn)
        corner(r, UDim.new(1, 0))
        tw(r, TI.rip, { Size = UDim2.fromOffset(big, big), BackgroundTransparency = 1 })
        task.delay(0.6, function() pcall(function() r:Destroy() end) end)
    end)
end
UIX.ripple = ripple
