local tip = new("Frame", { Size = UDim2.fromOffset(0, 26), AutomaticSize = Enum.AutomaticSize.X, AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 1, BorderSizePixel = 0,
    Visible = false, ZIndex = 80 }, gui)
bindTheme(tip, "BackgroundColor3", "panel2")
corner(tip, 8); pad(tip, 11, 0, 11, 0)
local tipStroke = stroke(tip, T.line, 1, 1)
bindTheme(tipStroke, "Color", "line")
local tipScale = new("UIScale", { Scale = 1 }, tip)
local tipLbl = label(tip, "", 12, "text", F.med, XL)
tipLbl.Size = UDim2.fromOffset(0, 26); tipLbl.AutomaticSize = Enum.AutomaticSize.X; tipLbl.TextTransparency = 1; tipLbl.ZIndex = 81
local tipTok = 0
local function showTip(row, text)
    tipTok = tipTok + 1
    local a, s = row.AbsolutePosition, row.AbsoluteSize
    tipScale.Scale = curScale()
    tip.Position = UDim2.fromOffset(a.X + s.X + 8, a.Y + s.Y / 2)
    tipLbl.Text = text
    tip.Visible = true
    tw(tip, TI.fast, { BackgroundTransparency = 0.04 })
    tw(tipStroke, TI.fast, { Transparency = 0 })
    tw(tipLbl, TI.fast, { TextTransparency = 0 })
end
local function hideTip()
    tipTok = tipTok + 1
    local my = tipTok
    tw(tip, TI.fast, { BackgroundTransparency = 1 })
    tw(tipStroke, TI.fast, { Transparency = 1 })
    tw(tipLbl, TI.fast, { TextTransparency = 1 })
    task.delay(0.14, function() if tipTok == my then pcall(function() tip.Visible = false end) end end)
end

local Page = {}
Page.__index = Page
local tabs, currentTab = {}, nil
UIX.tabs = tabs
UIX.tabByName = {}
local sbCollapsed = false
local listN = 0
local groupHeads = {}
local groups, groupList = {}, {}
UIX.groups, UIX.groupList = groups, groupList
local ROW_H, TOP_H, ROW_GAP = 34, 36, 2
local searchIdx = {}
UIX.searchIdx = searchIdx

local function st(o, props, snap)
    if snap then for k, v in pairs(props) do o[k] = v end else tw(o, TI.med, props) end
end

local function colScroller(parent, pos, size)
    local s = new("ScrollingFrame", {
        Position = pos, Size = size, BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageTransparency = 0.35,
        CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, ZIndex = 4,
    }, parent)
    bindTheme(s, "ScrollBarImageColor3", "acc")
    vlist(s, 9)
    pad(s, 0, 0, 7, 12)
    return s
end

function UIX.indexCtl(sec, text, frame, kind)
    if not sec or not sec.tab or type(text) ~= "string" or text == "" then return end
    local tn = sec.tab.name
    searchIdx[#searchIdx + 1] = {
        text = text, low = string.lower(text), hay = string.lower(text .. " " .. (sec.title or "") .. " " .. tn),
        tab = sec.tab, sec = sec.title or "", frame = frame, reveal = sec.reveal, kind = kind or "ctl",
    }
end

function UIX.tileCols(hue, sat)
    hue = hue or 220
    sat = sat or 1
    local a = hsv(hue, 0.58 * sat, 1):Lerp(T.acc, 0.2)
    local b = hsv(hue + 30, 0.70 * sat, 0.88):Lerp(T.acc2, 0.15)
    return a, b
end

local function paintTab(t, snap)
    local on = (currentTab == t)
    local hov = t.hover and not on
    local a, b = UIX.tileCols(t.hue, t.sat)
    t.tileG.Color = ColorSequence.new(a, b)
    st(t.bgF, { BackgroundTransparency = on and 0.86 or (hov and 0.93 or 1) }, snap)
    st(t.tile, { BackgroundTransparency = on and 0 or (hov and 0.6 or 0.8) }, snap)
    st(t.pill, { Size = UDim2.fromOffset(3, on and 18 or 0), BackgroundTransparency = on and 0 or 1 }, snap)
    st(t.lbl, { TextColor3 = (on or hov) and T.text or T.dim }, snap)
    local ic = on and WHITE or a:Lerp(WHITE, hov and 0.4 or 0.15)
    if snap then t.ico.ImageColor3 = ic else tw(t.ico, TI.med, { ImageColor3 = ic }) end
    local ph = t.ico:FindFirstChildOfClass("TextLabel")
    if ph then ph.TextColor3 = ic end
end

local function paintGroup(g, snap)
    local active = currentTab ~= nil and currentTab.group == g.key
    local lit = active or g.hover or g.open
    local a, b = UIX.tileCols(g.hue, g.sat)
    g.tileG.Color = ColorSequence.new(a, b)
    st(g.bgF, { BackgroundTransparency = g.open and 0.9 or (g.hover and 0.93 or 1) }, snap)
    st(g.tile, { BackgroundTransparency = active and 0 or (lit and 0.5 or 0.72) }, snap)
    st(g.lbl, { TextColor3 = lit and T.text or T.dim }, snap)
    local ic = active and WHITE or a:Lerp(WHITE, lit and 0.35 or 0.1)
    if snap then g.ico.ImageColor3 = ic else tw(g.ico, TI.med, { ImageColor3 = ic }) end
    local ph = g.ico:FindFirstChildOfClass("TextLabel")
    if ph then ph.TextColor3 = ic end
end

local function groupHeight(g)
    local s = 6
    for i, h in ipairs(g.items) do s = s + h + (i > 1 and ROW_GAP or 0) end
    return s
end
local function setGroupOpen(g, v, snap)
    if g.open == v and not snap then return end
    g.open = v
    local sz = UDim2.new(1, 0, 0, v and groupHeight(g) or 0)
    if snap then
        g.clip.Size = sz
        g.chev.Rotation = v and 0 or -90
    else
        tw(g.clip, TI.med, { Size = sz })
        tw(g.chev, TI.back, { Rotation = v and 0 or -90 })
    end
    paintGroup(g, snap)
end
local function openOnly(g, snap)
    for _, o in ipairs(groupList) do
        if o ~= g and o.open then setGroupOpen(o, false, snap) end
    end
    setGroupOpen(g, true, snap)
end
UIX.setGroupOpen, UIX.openGroupOnly = setGroupOpen, openOnly

function UIX.defGroup(key, title, iconName, hue, sat)
    if groups[key] then return groups[key] end
    listN = listN + 1
    local wrap = new("Frame", { Name = "grp_" .. key, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
        LayoutOrder = listN, BorderSizePixel = 0, ZIndex = 5 }, sideList)
    vlist(wrap, ROW_GAP)
    local row = new("TextButton", { Size = UDim2.new(1, 0, 0, TOP_H), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = 0,
        BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 5 }, wrap)
    corner(row, 10)
    local bgF = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5 }, row)
    corner(bgF, 10)
    bindGrad(new("UIGradient", {}, bgF), "lin")
    local tile = new("Frame", { Name = "tile", Size = UDim2.fromOffset(28, 28), Position = UDim2.fromOffset(7, 4), BackgroundColor3 = WHITE, BackgroundTransparency = 0.72,
        BorderSizePixel = 0, ZIndex = 6 }, row)
    corner(tile, 8)
    local tileG = new("UIGradient", { Rotation = 45 }, tile)
    local ico = icon(row, iconName or "ic_settings", 16, "dim")
    ico.Position = UDim2.fromOffset(13, 10); ico.ZIndex = 7
    local lbl = new("TextLabel", { BackgroundTransparency = 1, Text = title, TextSize = 13, Font = F.bold, TextXAlignment = XL,
        Position = UDim2.fromOffset(44, 0), Size = UDim2.new(1, -66, 1, 0), BorderSizePixel = 0, ZIndex = 7, TextTruncate = Enum.TextTruncate.AtEnd }, row)
    lbl.TextColor3 = T.dim
    local chev = chevron(row, "dim", 12)
    chev.Position = UDim2.new(1, -18, 0.5, 0); chev.ZIndex = 7; chev.Rotation = -90
    local clip = new("Frame", { Name = "clip", Size = UDim2.new(1, 0, 0, 0), BackgroundTransparency = 1, ClipsDescendants = true, LayoutOrder = 1, BorderSizePixel = 0, ZIndex = 5 }, wrap)
    local inner = new("Frame", { Name = "inner", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5 }, clip)
    vlist(inner, ROW_GAP)
    local ip = pad(inner, 10, 2, 0, 4)
    local rail = new("Frame", { Size = UDim2.new(0, 2, 1, -10), Position = UDim2.fromOffset(4, 5), BorderSizePixel = 0, BackgroundTransparency = 0.5, ZIndex = 5 }, clip)
    corner(rail, 1); bindTheme(rail, "BackgroundColor3", "line")
    local g = { key = key, title = title, row = row, wrap = wrap, bgF = bgF, tile = tile, tileG = tileG, hue = hue, sat = sat, ico = ico, lbl = lbl, chev = chev, clip = clip, inner = inner, ip = ip, rail = rail,
        open = false, hover = false, items = {}, tabs = {}, n = 0 }
    groups[key] = g
    groupList[#groupList + 1] = g
    row.MouseEnter:Connect(function()
        g.hover = true; paintGroup(g, false)
        if sbCollapsed then showTip(row, title) end
    end)
    row.MouseLeave:Connect(function() g.hover = false; paintGroup(g, false); hideTip() end)
    row.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(row, i.Position, "acc") end end)
    row.Activated:Connect(function()
        if g.open then setGroupOpen(g, false) else openOnly(g) end
    end)
    reg(function() paintGroup(g, true) end)
    paintGroup(g, true)
    return g
end

function UIX.SubHead(key, text)
    local g = groups[key]
    if not g then return end
    g.n = g.n + 1
    local h = new("Frame", { Size = UDim2.new(1, 0, 0, 20), BackgroundTransparency = 1, LayoutOrder = g.n, BorderSizePixel = 0, ZIndex = 5 }, g.inner)
    local lbl = new("TextLabel", { BackgroundTransparency = 1, Text = string.upper(text), TextSize = 9, Font = F.bold, TextXAlignment = XL,
        Position = UDim2.fromOffset(8, 7), Size = UDim2.new(1, -8, 0, 12), BorderSizePixel = 0, ZIndex = 5 }, h)
    bindTheme(lbl, "TextColor3", "dim")
    local ln = new("Frame", { Size = UDim2.new(1, -14, 0, 1), Position = UDim2.fromOffset(2, 12), BorderSizePixel = 0, BackgroundTransparency = 1, ZIndex = 5 }, h)
    bindTheme(ln, "BackgroundColor3", "line")
    groupHeads[#groupHeads + 1] = { frame = h, lbl = lbl, line = ln }
    g.items[#g.items + 1] = 20
    if g.open then g.clip.Size = UDim2.new(1, 0, 0, groupHeight(g)) end
end

local function Tab(name, iconName, group)
    local g = group and groups[group] or nil
    local parent, rowH, order = sideList, TOP_H, 0
    if g then
        g.n = g.n + 1; parent = g.inner; rowH = ROW_H; order = g.n
    else
        listN = listN + 1; order = listN
    end
    local row = new("TextButton", { Size = UDim2.new(1, 0, 0, rowH), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = order,
        BorderSizePixel = 0, ClipsDescendants = true, ZIndex = 5 }, parent)
    corner(row, 10)
    local bgF = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 5 }, row)
    corner(bgF, 10)
    bindGrad(new("UIGradient", {}, bgF), "lin")
    local pill = new("Frame", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 0, 0.5, 0), Size = UDim2.fromOffset(3, 0), BackgroundColor3 = WHITE,
        BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 7 }, row)
    corner(pill, 2)
    bindGrad(new("UIGradient", { Rotation = 90 }, pill), "lin")
    local tileS = (rowH >= TOP_H) and 28 or 26
    local tile = new("Frame", { Name = "tile", Size = UDim2.fromOffset(tileS, tileS), Position = UDim2.fromOffset(7 + (28 - tileS) / 2, math.floor((rowH - tileS) / 2)),
        BackgroundColor3 = WHITE, BackgroundTransparency = 0.8, BorderSizePixel = 0, ZIndex = 6 }, row)
    corner(tile, 8)
    local tileG = new("UIGradient", { Rotation = 45 }, tile)
    local ico = icon(row, iconName or "ic_settings", 16, "dim")
    ico.Position = UDim2.fromOffset(13, math.floor((rowH - 16) / 2)); ico.ZIndex = 7
    local lbl = new("TextLabel", { BackgroundTransparency = 1, Text = name, TextSize = 13, Font = F.med, TextXAlignment = XL,
        Position = UDim2.fromOffset(44, 0), Size = UDim2.new(1, -48, 1, 0), BorderSizePixel = 0, ZIndex = 7, TextTruncate = Enum.TextTruncate.AtEnd }, row)
    lbl.TextColor3 = T.dim
    local page = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Visible = false, BorderSizePixel = 0, ZIndex = 4 }, pageHost)
    local empty = new("Frame", { Name = "empty", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 4 }, page)
    local eIc = icon(empty, iconName or "ic_settings", 56, "dim")
    eIc.AnchorPoint = Vector2.new(0.5, 0.5); eIc.Position = UDim2.new(0.5, 0, 0.5, -44); eIc.ImageTransparency = 0.6; eIc.ZIndex = 4
    local eT = label(empty, name, 20, "text", F.bold, XC)
    eT.AnchorPoint = Vector2.new(0.5, 0); eT.Position = UDim2.new(0.5, 0, 0.5, -4); eT.Size = UDim2.fromOffset(300, 26); eT.ZIndex = 4
    local eS = label(empty, "Nothing here yet. This page is reserved for your own functions.", 12, "dim", F.reg, XC)
    eS.AnchorPoint = Vector2.new(0.5, 0); eS.Position = UDim2.new(0.5, 0, 0.5, 24); eS.Size = UDim2.fromOffset(300, 34); eS.TextWrapped = true; eS.ZIndex = 4
    local t = setmetatable({
        btn = row, bgF = bgF, tile = tile, tileG = tileG, pill = pill, ico = ico, lbl = lbl, page = page, name = name, group = g and g.key or nil, groupTitle = g and g.title or nil,
        secs = {}, nL = 0, nR = 0, compact = false, hover = false, empty = empty, rowH = rowH,
        left = colScroller(page, UDim2.fromOffset(0, 0), UDim2.new(0.5, -5, 1, 0)),
        right = colScroller(page, UDim2.new(0.5, 5, 0, 0), UDim2.new(0.5, -5, 1, 0)),
    }, Page)
    tabs[#tabs + 1] = t
    UIX.tabByName[name] = t
    if g then
        g.items[#g.items + 1] = rowH
        g.tabs[#g.tabs + 1] = t
        if g.open then g.clip.Size = UDim2.new(1, 0, 0, groupHeight(g)) end
    end
    searchIdx[#searchIdx + 1] = { text = name, low = string.lower(name), hay = string.lower(name .. " " .. (g and g.title or "")), tab = t, sec = g and g.title or "", kind = "tab" }
    reg(function(snap) paintTab(t, true) end)
    row.MouseEnter:Connect(function()
        t.hover = true; paintTab(t, false)
        if sbCollapsed then showTip(row, name) end
    end)
    row.MouseLeave:Connect(function() t.hover = false; paintTab(t, false); hideTip() end)
    row.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(row, i.Position, "acc") end end)
    row.Activated:Connect(function() if currentTab ~= t then UIX.selectTab(t) end end)
    paintTab(t, true)
    return t
end
UIX.Tab = Tab

function UIX.placeTab(t, rowH)
    t.rowH = rowH
    local tileS = (rowH >= TOP_H) and 28 or 26
    t.btn.Size = UDim2.new(1, 0, 0, rowH)
    t.tile.Size = UDim2.fromOffset(tileS, tileS)
    t.tile.Position = UDim2.fromOffset(7 + (28 - tileS) / 2, math.floor((rowH - tileS) / 2))
    t.ico.Position = UDim2.fromOffset(13, math.floor((rowH - 16) / 2))
end

function UIX.arrange(layout)
    local placed = {}
    for gi, L in ipairs(layout) do
        local g = groups[L.key] or UIX.defGroup(L.key, L.title, L.icon, L.hue, L.sat)
        g.hue, g.sat = L.hue, L.sat
        g.wrap.LayoutOrder = gi
        g.n, g.items, g.tabs = 0, {}, {}
        for _, e in ipairs(L.items) do
            if type(e) == "table" then
                UIX.SubHead(L.key, e.sub)
            else
                local t = UIX.tabByName[e]
                if t and not placed[t] then
                    placed[t] = true
                    g.n = g.n + 1
                    t.btn.Parent = g.inner
                    t.btn.LayoutOrder = g.n
                    UIX.placeTab(t, ROW_H)
                    t.group, t.groupTitle, t.hue, t.sat = g.key, g.title, L.hue, L.sat
                    g.items[#g.items + 1] = ROW_H
                    g.tabs[#g.tabs + 1] = t
                    for _, e2 in ipairs(searchIdx) do
                        if e2.tab == t and e2.kind == "tab" then
                            e2.sec = g.title
                            e2.hay = string.lower(t.name .. " " .. g.title)
                        end
                    end
                end
            end
        end
        if g.open then g.clip.Size = UDim2.new(1, 0, 0, groupHeight(g)) end
    end
    local extra = #layout
    for _, t in ipairs(tabs) do
        if not placed[t] and not t.group then extra = extra + 1; t.btn.LayoutOrder = extra end
    end
    for _, t in ipairs(tabs) do paintTab(t, true) end
    for _, g in ipairs(groupList) do paintGroup(g, true) end
end

function Page:setCompact(c)
    if c == self.compact then return end
    self.compact = c
    if c then
        self.right.Visible = false
        self.left.Size = UDim2.fromScale(1, 1)
        for _, s in ipairs(self.secs) do
            if s.side == "R" then s.holder.Parent = self.left; s.holder.LayoutOrder = 1000 + s.order end
        end
    else
        self.right.Visible = true
        self.left.Size = UDim2.new(0.5, -5, 1, 0)
        for _, s in ipairs(self.secs) do
            if s.side == "R" then s.holder.Parent = self.right; s.holder.LayoutOrder = s.order end
        end
    end
end

function Page:Section(side_, title_, grp, iconName)
    local isR = (side_ == "R")
    local col = isR and self.right or self.left
    if isR then self.nR = self.nR + 1 else self.nL = self.nL + 1 end
    local order = isR and self.nR or self.nL
    local holder = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 0.18, BorderSizePixel = 0,
        LayoutOrder = (self.compact and isR) and (1000 + order) or order, ZIndex = 4 })
    bindTheme(holder, "BackgroundColor3", "panel")
    glassUse("sec", holder, 0.18)
    corner(holder, 11)
    local hs = stroke(holder, T.line, 1, 0.25)
    bindTheme(hs, "Color", "line")
    pad(holder, 11, 10, 11, 11)
    vlist(holder, 7)
    local hdRow = new("Frame", { Size = UDim2.new(1, 0, 0, 16), BackgroundTransparency = 1, LayoutOrder = 0, BorderSizePixel = 0, ZIndex = 5 }, holder)
    local bar = new("Frame", { Size = UDim2.fromOffset(3, 12), Position = UDim2.fromOffset(0, 2), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 5 }, hdRow)
    corner(bar, 2); bindGrad(new("UIGradient", { Rotation = 90 }, bar), "lin")
    local hd = label(hdRow, string.upper(title_), 11, "dim", F.bold, XL)
    hd.Size = UDim2.new(1, -12, 1, 0); hd.Position = UDim2.fromOffset(11, 0); hd.ZIndex = 5
    local body = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = 1, BorderSizePixel = 0, ZIndex = 5 }, holder)
    vlist(body, 4)
    local cover = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 60, Visible = false, Active = false }, holder)
    bindTheme(cover, "BackgroundColor3", "panel")
    corner(cover, 11)
    holder.Parent = (self.compact and isR) and self.left or col
    local rec = { holder = holder, side = side_, order = order, cover = cover, tok = 0 }
    self.secs[#self.secs + 1] = rec
    if self.empty then self.empty.Visible = false end
    local sec = setmetatable({ body = body, grp = grp, n = 0, tab = self, title = title_ }, UIX.Sec)
    searchIdx[#searchIdx + 1] = { text = title_, low = string.lower(title_), hay = string.lower(title_ .. " " .. self.name), tab = self, sec = self.name, frame = holder, kind = "section", stroke = hs }
    return sec
end

local function revealPage(t)
    local k = 0
    for _, s in ipairs(t.secs) do
        k = k + 1
        s.tok = s.tok + 1
        local my = s.tok
        local cv = s.cover
        cv.Visible = true
        cv.BackgroundTransparency = 0
        local delay = ((s.order - 1) * 0.05) + (s.side == "R" and 0.03 or 0)
        task.delay(delay, function()
            if s.tok ~= my then return end
            tw(cv, TI.slow, { BackgroundTransparency = 1 })
            task.delay(0.5, function() if s.tok == my then pcall(function() cv.Visible = false end) end end)
        end)
    end
end

UIX.revealPage = revealPage

local function setCrumb(t)
    crumbGroup.Text = string.upper(t.groupTitle or BRAND_TITLE)
    crumbName.Text = t.name
end

local function ensureVisible(row)
    pcall(function()
        if not alive(row) then return end
        local sc = curScale()
        local ra, rs = row.AbsolutePosition, row.AbsoluteSize
        local la, ls = sideList.AbsolutePosition, sideList.AbsoluteSize
        if ls.Y < 10 or rs.Y < 1 then return end
        local cur = sideList.CanvasPosition.Y
        if ra.Y < la.Y then
            tw(sideList, TI.med, { CanvasPosition = Vector2.new(0, math.max(0, cur - (la.Y - ra.Y) / sc - 30)) })
        elseif ra.Y + rs.Y > la.Y + ls.Y then
            tw(sideList, TI.med, { CanvasPosition = Vector2.new(0, cur + (ra.Y + rs.Y - la.Y - ls.Y) / sc + 30) })
        end
    end)
end

function UIX.selectTab(t, instant)
    if UIX.closeDD then UIX.closeDD() end
    local old = currentTab
    currentTab = t
    local g = t.group and groups[t.group] or nil
    if g and not g.open then openOnly(g, instant) end
    for _, x in ipairs(tabs) do
        local on = (x == t)
        if x.page.Visible ~= on then x.page.Visible = on end
        paintTab(x, instant)
    end
    for _, gg in ipairs(groupList) do paintGroup(gg, instant) end
    setCrumb(t)
    if g then task.delay(instant and 0.05 or 0.3, function() ensureVisible(t.btn) end) end
    if not instant and old ~= t then
        t.page.Position = UDim2.fromOffset(0, 12)
        tw(t.page, TI.slow, { Position = UDim2.fromOffset(0, 0) })
        revealPage(t)
    else
        t.page.Position = UDim2.fromOffset(0, 0)
        for _, s in ipairs(t.secs) do s.tok = s.tok + 1; s.cover.Visible = false end
    end
end
UIX.getTab = function() return currentTab end

local function setSidebar(collapsed, snap)
    if collapsed == sbCollapsed and not snap then return end
    sbCollapsed = collapsed
    local w = collapsed and SB_SHUT or SB_OPEN
    sbNow = w
    local sz, mp, ms = UDim2.new(0, w, 1, 0), UDim2.fromOffset(w, 0), UDim2.new(1, -w, 1, 0)
    local ta = collapsed and 1 or 0
    local padL = UDim.new(0, collapsed and 0 or 10)
    local railT = collapsed and 1 or 0.5
    if snap then
        side.Size = sz; main.Position = mp; main.Size = ms
        for _, t in ipairs(tabs) do t.lbl.TextTransparency = ta end
        for _, g in ipairs(groupList) do g.lbl.TextTransparency = ta; g.chev.Visible = not collapsed; g.ip.PaddingLeft = padL; g.rail.BackgroundTransparency = railT end
        for _, g in ipairs(groupHeads) do g.lbl.TextTransparency = ta; g.line.BackgroundTransparency = collapsed and 0.4 or 1 end
        brandTitle.TextTransparency = ta; brandSub.TextTransparency = ta; statusLbl.TextTransparency = ta
        collapseIc.Rotation = collapsed and 180 or 0
    else
        tw(side, TI.slow, { Size = sz }); tw(main, TI.slow, { Position = mp, Size = ms })
        for _, t in ipairs(tabs) do tw(t.lbl, TI.med, { TextTransparency = ta }) end
        for _, g in ipairs(groupList) do
            tw(g.lbl, TI.med, { TextTransparency = ta }); g.chev.Visible = not collapsed
            tw(g.ip, TI.med, { PaddingLeft = padL }); tw(g.rail, TI.med, { BackgroundTransparency = railT })
        end
        for _, g in ipairs(groupHeads) do tw(g.lbl, TI.med, { TextTransparency = ta }); tw(g.line, TI.med, { BackgroundTransparency = collapsed and 0.4 or 1 }) end
        tw(brandTitle, TI.med, { TextTransparency = ta }); tw(brandSub, TI.med, { TextTransparency = ta }); tw(statusLbl, TI.med, { TextTransparency = ta })
        tw(collapseIc, TI.slow, { Rotation = collapsed and 180 or 0 })
    end
end
UIX.setSidebar = setSidebar
UIX.sbCollapsed = function() return sbCollapsed end
collapseBtn.Activated:Connect(function()
    if UIX.forcedShut then return end
    cfg.sbCollapsed = not cfg.sbCollapsed
    mark("ui")
end)
collapseBtn.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(collapseBtn, i.Position, "acc") end end)

do
local sOpen = false
local sBar = new("Frame", { Name = "searchBar", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -44, 0, 6), Size = UDim2.fromOffset(28, 28), BackgroundTransparency = 0,
    BorderSizePixel = 0, ClipsDescendants = true, Visible = false, ZIndex = 20 }, top)
bindTheme(sBar, "BackgroundColor3", "panel2")
corner(sBar, 14)
local sStroke = stroke(sBar, T.acc, 1.2, 0.35)
bindTheme(sStroke, "Color", "acc")
local sIc = icon(sBar, "ic_search", 14, "acc")
sIc.Position = UDim2.fromOffset(8, 7); sIc.ZIndex = 21
local sBox = new("TextBox", { Size = UDim2.new(1, -66, 1, 0), Position = UDim2.fromOffset(30, 0), BackgroundTransparency = 1, Text = "", PlaceholderText = "search any function...",
    Font = F.med, TextSize = 13, TextXAlignment = XL, ClearTextOnFocus = false, BorderSizePixel = 0, ZIndex = 21 }, sBar)
bindTheme(sBox, "TextColor3", "text"); bindTheme(sBox, "PlaceholderColor3", "dim")
local sClose = new("TextButton", { Size = UDim2.fromOffset(24, 24), Position = UDim2.new(1, -27, 0, 2), BackgroundTransparency = 1, Text = "", AutoButtonColor = false,
    BorderSizePixel = 0, ZIndex = 21 }, sBar)
local sCloseIc = icon(sClose, "ic_close", 11, "dim")
sCloseIc.AnchorPoint = Vector2.new(0.5, 0.5); sCloseIc.Position = UDim2.fromScale(0.5, 0.5); sCloseIc.ZIndex = 22

local sRes = new("Frame", { Name = "searchRes", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -44, 0, 40), Size = UDim2.fromOffset(300, 0), BackgroundTransparency = 0.02,
    BorderSizePixel = 0, ClipsDescendants = true, Visible = false, ZIndex = 30 }, main)
bindTheme(sRes, "BackgroundColor3", "panel")
corner(sRes, 12)
local sResSt = stroke(sRes, T.acc, 1.2, 0.45)
bindTheme(sResSt, "Color", "acc")
local sList = new("ScrollingFrame", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3, ScrollBarImageTransparency = 0.3,
    CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ScrollingDirection = Enum.ScrollingDirection.Y, ZIndex = 31 }, sRes)
bindTheme(sList, "ScrollBarImageColor3", "acc")
vlist(sList, 2); pad(sList, 6, 6, 6, 6)
local sNone = label(sRes, "No function matches", 12, "dim", F.med, XC)
sNone.Size = UDim2.new(1, 0, 0, 30); sNone.Position = UDim2.fromOffset(0, 8); sNone.ZIndex = 32; sNone.Visible = false

local function searchW() return clamp(DW - sbNow - 70, 130, 340) end
local function resW() return clamp(DW - sbNow - 20, 220, 380) end

local function runSearch(q)
    q = string.lower(q or "")
    local toks = {}
    for w in string.gmatch(q, "%S+") do toks[#toks + 1] = w end
    local out = {}
    if #toks == 0 then
        for i, e in ipairs(searchIdx) do
            if e.kind == "tab" then out[#out + 1] = { e = e, sc = i } end
        end
        return out
    end
    for i, e in ipairs(searchIdx) do
        local ok = true
        for _, tk in ipairs(toks) do
            if not string.find(e.hay, tk, 1, true) then ok = false; break end
        end
        if ok then
            local sc = 3
            if string.sub(e.low, 1, #toks[1]) == toks[1] then sc = 0
            elseif string.find(e.low, toks[1], 1, true) then sc = 1
            elseif e.kind == "ctl" then sc = 2 end
            if e.kind == "tab" then sc = sc - 0.6 elseif e.kind == "section" then sc = sc - 0.3 end
            out[#out + 1] = { e = e, sc = sc + i / 100000 }
        end
    end
    table.sort(out, function(a, b) return a.sc < b.sc end)
    return out
end

local function pulseCtl(e)
    local f = e.frame
    if not f or not alive(f) then return end
    if e.kind == "section" then
        local s = e.stroke
        if s and alive(s) then
            task.spawn(function()
                for _ = 1, 3 do
                    s.Color = T.acc; s.Thickness = 2.6; s.Transparency = 0
                    tw(s, TI.rip, { Thickness = 1, Transparency = 0.25 })
                    task.wait(0.55)
                    if not alive(s) then return end
                end
                s.Color = T.line
            end)
        end
        return
    end
    task.spawn(function()
        for _ = 1, 3 do
            if not alive(f) then return end
            f.BackgroundColor3 = T.acc
            f.BackgroundTransparency = 0.55
            tw(f, TI.rip, { BackgroundTransparency = 1 })
            task.wait(0.55)
        end
        if alive(f) then f.BackgroundColor3 = T.panel2 end
    end)
end

local function focusCtl(e)
    local f = e.frame
    if not f or not alive(f) then return end
    local sc = f:FindFirstAncestorWhichIsA("ScrollingFrame")
    if sc then
        local s = curScale()
        local cur = sc.CanvasPosition.Y
        local y = (f.AbsolutePosition.Y - sc.AbsolutePosition.Y) / s + cur - 10
        tw(sc, TI.slow, { CanvasPosition = Vector2.new(0, math.max(0, y)) })
    end
    pulseCtl(e)
end

local closeSearch
local function gotoEntry(e)
    if closeSearch then closeSearch() end
    local same = (currentTab == e.tab)
    if not same then UIX.selectTab(e.tab) end
    if e.frame then
        if e.reveal then pcall(e.reveal) end
        task.delay(same and 0.32 or 0.45, function() pcall(focusCtl, e) end)
    end
end
UIX.gotoEntry = gotoEntry

local sRows, sFirst = {}, nil
local function rebuildResults(q)
    for _, r in ipairs(sRows) do pcall(function() r:Destroy() end) end
    sRows = {}
    local res = runSearch(q)
    local n = math.min(#res, 40)
    sFirst = res[1] and res[1].e or nil
    for i = 1, n do
        local e = res[i].e
        local b = new("TextButton", { Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = T.acc, BackgroundTransparency = 1, Text = "", AutoButtonColor = false, LayoutOrder = i,
            BorderSizePixel = 0, ZIndex = 32 }, sList)
        corner(b, 8)
        local nameTxt = e.text
        local tl = new("TextLabel", { BackgroundTransparency = 1, Text = nameTxt, TextSize = 13, Font = (e.kind == "ctl") and F.med or F.bold, TextXAlignment = XL,
            TextColor3 = T.text, Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -118, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd, BorderSizePixel = 0, ZIndex = 33 }, b)
        local where = (e.kind == "tab") and ((e.sec ~= "" and e.sec .. " / " or "") .. "page") or (e.tab.name .. ((e.kind == "ctl" and e.sec ~= "" and e.sec ~= e.text) and (" / " .. e.sec) or ""))
        local pl = new("TextLabel", { BackgroundTransparency = 1, Text = where, TextSize = 10, Font = F.reg, TextXAlignment = XR, TextColor3 = T.dim,
            Position = UDim2.new(1, -108, 0, 0), Size = UDim2.fromOffset(100, 34), TextTruncate = Enum.TextTruncate.AtEnd, BorderSizePixel = 0, ZIndex = 33 }, b)
        b.MouseEnter:Connect(function() tw(b, TI.fast, { BackgroundTransparency = 0.82 }) end)
        b.MouseLeave:Connect(function() tw(b, TI.fast, { BackgroundTransparency = 1 }) end)
        b.Activated:Connect(function() gotoEntry(e) end)
        sRows[i] = b
    end
    sNone.Visible = (n == 0)
    local h = (n == 0) and 46 or clamp(n * 36 + 12, 46, 330)
    tw(sRes, TI.med, { Size = UDim2.fromOffset(resW(), h) })
end

local function openSearch()
    if sOpen then return end
    sOpen = true
    if UIX.closeDD then UIX.closeDD() end
    sBar.Visible = true
    sBar.Size = UDim2.fromOffset(28, 28)
    tw(sBar, TI.back, { Size = UDim2.fromOffset(searchW(), 28) })
    sRes.Visible = true
    sRes.Size = UDim2.fromOffset(resW(), 0)
    rebuildResults(sBox.Text)
    task.delay(0.05, function() pcall(function() sBox:CaptureFocus() end) end)
end
closeSearch = function()
    if not sOpen then return end
    sOpen = false
    pcall(function() sBox:ReleaseFocus() end)
    tw(sBar, TI.inq, { Size = UDim2.fromOffset(28, 28) })
    tw(sRes, TI.inq, { Size = UDim2.fromOffset(sRes.Size.X.Offset, 0) })
    task.delay(0.22, function()
        if not sOpen then sBar.Visible = false; sRes.Visible = false; sBox.Text = "" end
    end)
end
UIX.openSearch, UIX.closeSearch = openSearch, function() if closeSearch then closeSearch() end end
UIX.searchOpen = function() return sOpen end
UIX._search = { box = sBox, rows = function() return sRows end, first = function() return sFirst end, res = sRes }
sBox:GetPropertyChangedSignal("Text"):Connect(function() if sOpen then rebuildResults(sBox.Text) end end)
sBox.FocusLost:Connect(function(enter)
    if enter and sOpen and sFirst then gotoEntry(sFirst) end
end)
sClose.Activated:Connect(function() closeSearch() end)
searchBtn.Activated:Connect(function() if sOpen then closeSearch() else openSearch() end end)
searchBtn.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(searchBtn, i.Position, "acc") end end)
searchBtn.MouseEnter:Connect(function() tw(searchBtn, TI.fast, { BackgroundTransparency = 0.1 }) end)
searchBtn.MouseLeave:Connect(function() tw(searchBtn, TI.fast, { BackgroundTransparency = 0.35 }) end)
bind(UIS.InputBegan, function(i)
    if sOpen and i.KeyCode == Enum.KeyCode.Escape then closeSearch() end
end)
end

local function basePos()
    return UDim2.new(0.5, winOff.X, 0.5, winOff.Y)
end
UIX.basePos = basePos
local function clampOff()
    local vp = viewport()
    local s = curScale()
    local w, h = DW * s, DH * s
    local minX, maxX = w / 2 - vp.X / 2 - (w - 120), vp.X / 2 - 120 + w / 2
    local minY, maxY = h / 2 - vp.Y / 2, vp.Y / 2 - 60 + h / 2
    winOff = Vector2.new(clamp(winOff.X, minX, maxX), clamp(winOff.Y, minY, maxY))
end
function UIX.layout(snap)
    local vp = viewport()
    local s = clamp(tonumber(C("uiScale")) or 1, 0.4, 1.6)
    local smax = math.min((vp.X - 16) / 420, (vp.Y - 16) / 280)
    if smax > 0.3 then s = math.min(s, smax) end
    s = math.max(s, 0.4)
    scaleObj.Scale = s
    DW = clamp(math.floor(vp.X / s - 16), 420, 760)
    DH = clamp(math.floor(vp.Y / s - 16), 280, 470)
    shell.Size = UDim2.fromOffset(DW, DH)
    local forced = DW < 640
    UIX.forcedShut = forced
    local col = forced or (C("sbCollapsed") == true)
    setSidebar(col, snap)
    collapseBtn.Visible = not forced
    local innerW = DW - (col and SB_SHUT or SB_OPEN)
    local compact = innerW < 520
    for _, t in ipairs(tabs) do t:setCompact(compact) end
    for i, b in ipairs(blobs) do b.Size = UDim2.fromOffset(DW * 0.8, DW * 0.8) end
    clampOff()
    if not UIX.animating then shell.Position = basePos() end
end

local winDrag
top.InputBegan:Connect(function(i)
    if isPress(i) then winDrag = { start = i.Position, off = winOff } end
end)
bind(UIS.InputChanged, function(i)
    if not isMove(i) then return end
    local d = UIX.drag
    if d.fn then d.fn(i) end
    if winDrag then
        local dl = i.Position - winDrag.start
        winOff = winDrag.off + Vector2.new(dl.X, dl.Y)
        clampOff()
        shell.Position = basePos()
    end
end)
bind(UIS.InputEnded, function(i)
    if isPress(i) then
        UIX.drag.fn = nil
        winDrag = nil
        if UIX.drag.lock then UIX.drag.lock.ScrollingEnabled = true; UIX.drag.lock = nil end
        if UIX.dragEnd then local e = UIX.dragEnd; UIX.dragEnd = nil; pcall(e) end
    end
end)
pcall(function()
    local c = cam()
    if c then bind(c:GetPropertyChangedSignal("ViewportSize"), function() mark("ui") end) end
end)

local bg = { sig = "", token = 0, tex = nil, custom = false, px = 0, py = 0 }
local function scenePick()
    local sc = C("bgScene")
    local id = tostring(C("bgId") or ""):match("%d+")
    local th = T.theme
    if sc == "None" then return nil end
    if sc == "Custom image" or (sc == "Theme default" and T.name == "Waifu" and id) then
        if id then return { id = id } end
        return th and th.scene and { tex = th.scene } or nil
    end
    if sc == "Theme default" then return th and th.scene and { tex = th.scene } or nil end
    local tx = UIX.SCENES[sc]
    return tx and { tex = tx } or nil
end

local function fadeInBg()
    bgImg.ImageTransparency = 1
    tw(bgImg, TI.slow, { ImageTransparency = 0 })
end

local function applyBgTex()
    if not bg.tex then return end
    local u = Assets.tex[bg.tex]
    if u and bgImg.Image ~= u then
        bgImg.Image = u
        fadeInBg()
    end
end
Assets.watchers[#Assets.watchers + 1] = applyBgTex

local function loadCustomBg(id, tok)
    local sheet = C("bgSheet") == true
    local mode = C("bgIdMode") or "Auto"
    local urls = {}
    if mode ~= "Thumbnail" or sheet then urls[#urls + 1] = "rbxassetid://" .. id end
    if mode ~= "Asset id" and not sheet then urls[#urls + 1] = ("rbxthumb://type=Asset&id=%s&w=768&h=432"):format(id) end
    for _, url in ipairs(urls) do
        bgImg.Image = url
        local t0 = os.clock()
        local ok = false
        while os.clock() - t0 < 3.5 do
            if tok ~= bg.token then return end
            local okL, ld = pcall(function() return bgImg.IsLoaded end)
            if okL and ld then ok = true; break end
            task.wait(0.1)
        end
        if ok then
            if tok == bg.token then fadeInBg() end
            return
        end
    end
    if tok ~= bg.token then return end
    notify("Background image " .. id .. " did not load (use a Decal/Image asset id)", 4)
    bg.custom = false
    local th = T.theme
    bg.tex = th and th.scene or nil
    bgImg.Image = ""
    bgImg.ImageRectOffset = Vector2.new(0, 0); bgImg.ImageRectSize = Vector2.new(0, 0)
    if not bg.tex then bgImg.Visible = false end
    applyBgTex()
end

function UIX.applyBackground(force)
    local w = scenePick()
    local sheet = C("bgSheet") == true
    local sig = (w and (w.tex or ("id" .. w.id)) or "none") .. "|" .. tostring(C("bgIdMode")) .. "|" .. tostring(sheet) .. "|" .. tostring(C("bgFW")) .. "x" .. tostring(C("bgFH"))
    local dim = clamp(tonumber(C("bgDim")) or 0.55, 0, 0.97)
    bgDim.BackgroundTransparency = w and (1 - dim) or 1
    if sig == bg.sig and not force then return end
    bg.sig = sig
    bg.token = bg.token + 1
    local tok = bg.token
    bg.tex, bg.custom = nil, false
    bgImg.ImageRectOffset = Vector2.new(0, 0)
    bgImg.ImageRectSize = Vector2.new(0, 0)
    if not w then
        bgImg.Visible = false
        bgImg.Image = ""
        return
    end
    bgImg.Visible = true
    if w.tex then
        bg.tex = w.tex
        bgImg.Image = ""
        applyBgTex()
    else
        bg.custom = true
        bgImg.Image = ""
        task.spawn(loadCustomBg, w.id, tok)
    end
end

local function bgStep(t, dt)
    if not bgImg.Visible then return end
    if bg.custom and C("bgSheet") == true then
        local cols, rows = math.max(1, math.floor(tonumber(C("bgCols")) or 4)), math.max(1, math.floor(tonumber(C("bgRows")) or 4))
        local fw, fh = math.max(1, tonumber(C("bgFW")) or 256), math.max(1, tonumber(C("bgFH")) or 256)
        local fps = clamp(tonumber(C("bgFps")) or 12, 1, 60)
        local n = cols * rows
        local idx = math.floor(t * fps) % n
        bgImg.ImageRectSize = Vector2.new(fw, fh)
        bgImg.ImageRectOffset = Vector2.new((idx % cols) * fw, math.floor(idx / cols) * fh)
    end
    local m = C("bgMotion")
    if m == "None" or UIX.perfTier >= 3 or C("uiLite") then
        if bgImg.Size.X.Scale ~= 1 then bgImg.Size = UDim2.fromScale(1, 1); bgImg.Position = UDim2.fromScale(0.5, 0.5) end
        return
    end
    local touch = UIS.TouchEnabled and not UIS.MouseEnabled
    if m == "Parallax" and touch then m = "Drift" end
    if m == "Drift" then
        bgImg.Size = UDim2.fromScale(1.14, 1.14)
        bgImg.Position = UDim2.fromScale(0.5 + math.sin(t * 0.13) * 0.035, 0.5 + math.cos(t * 0.1) * 0.025)
    elseif m == "Breathe" then
        local s = 1.05 + math.sin(t * 0.5) * 0.045
        bgImg.Size = UDim2.fromScale(s, s)
        bgImg.Position = UDim2.fromScale(0.5, 0.5)
    elseif m == "Parallax" then
        local mp = UIS:GetMouseLocation()
        local a, s = shell.AbsolutePosition, shell.AbsoluteSize
        local cx, cy = a.X + s.X / 2, a.Y + s.Y / 2
        local tx = clamp((mp.X - cx) / math.max(s.X, 1), -0.6, 0.6) * -0.07
        local ty = clamp((mp.Y - cy) / math.max(s.Y, 1), -0.6, 0.6) * -0.07
        local k = damp(5, dt)
        bg.px = bg.px + (tx - bg.px) * k
        bg.py = bg.py + (ty - bg.py) * k
        bgImg.Size = UDim2.fromScale(1.16, 1.16)
        bgImg.Position = UDim2.fromScale(0.5 + bg.px, 0.5 + bg.py)
    end
end

local function cPetal() return Color3.fromRGB(255, math.random(160, 205), math.random(200, 232)) end
local KINDS = {
    Petals = { tex = "petal", sz = { 9, 17 }, vy = { 20, 38 }, vx = { 6, 18 }, spin = { -120, 120 }, sway = 16, alpha = 0.18, dir = 1, col = cPetal },
    Snow = { tex = "flake", sz = { 5, 11 }, vy = { 16, 30 }, vx = { -6, 6 }, spin = { -40, 40 }, sway = 10, alpha = 0.3, dir = 1, col = function() return WHITE end },
    Embers = { tex = "dot", sz = { 3, 7 }, vy = { 22, 48 }, vx = { -8, 10 }, spin = { 0, 0 }, sway = 12, alpha = 0.1, dir = -1,
        col = function() return Color3.fromRGB(255, math.random(110, 180), math.random(40, 80)) end },
    Bubbles = { tex = "ring", sz = { 8, 18 }, vy = { 10, 24 }, vx = { -4, 4 }, spin = { 0, 0 }, sway = 8, alpha = 0.45, dir = -1, col = function() return Color3.fromRGB(176, 232, 255) end },
    Hearts = { tex = "heart", sz = { 9, 15 }, vy = { 16, 32 }, vx = { -6, 6 }, spin = { -30, 30 }, sway = 10, alpha = 0.25, dir = -1, col = function() return Color3.fromRGB(255, 124, 192) end },
    Stars = { tex = "star", sz = { 5, 11 }, vy = { -3, -1 }, vx = { -2, 2 }, spin = { 0, 0 }, sway = 0, alpha = 0.15, dir = 1, twinkle = true, col = function() return Color3.fromRGB(255, 244, 214) end },
    Sparkles = { tex = "spark", sz = { 8, 17 }, vy = { -8, -2 }, vx = { -3, 3 }, spin = { 0, 0 }, sway = 0, alpha = 0.1, dir = 1, twinkle = true, col = function() return math.random() < 0.5 and T.acc or T.acc2 end },
}
UIX.KINDS = KINDS
local pool, poolN, partKind, partActive, partAcc = {}, 24, nil, 0, 0
for i = 1, poolN do
    local f = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, Image = "", ImageTransparency = 1, Size = UDim2.fromOffset(10, 10),
        Visible = false, BorderSizePixel = 0, ZIndex = 15 }, fxTop)
    pool[i] = { f = f, x = 0, y = 0, vx = 0, vy = 0, rot = 0, vr = 0, ph = 0, sw = 1, life = 0, max = 1, size = 10 }
end

local function respawn(p, def, initial)
    local W, H = DW, DH
    local u = math.random()
    p.size = rnd(def.sz[1], def.sz[2])
    p.f.Size = UDim2.fromOffset(p.size, p.size)
    p.f.ImageColor3 = def.col()
    p.vx = rnd(def.vx[1], def.vx[2])
    p.vy = rnd(def.vy[1], def.vy[2])
    p.vr = rnd(def.spin[1], def.spin[2])
    p.ph = math.random() * 6.28
    p.sw = rnd(0.6, 1.6)
    p.rot = math.random() * 360
    p.life = 0
    p.max = rnd(1.8, 3.6)
    p.x = math.random() * W
    if def.twinkle then
        p.y = math.random() * H
        p.life = initial and (math.random() * p.max) or 0
    elseif def.dir == 1 then
        p.y = initial and (math.random() * H) or -12
    else
        p.y = initial and (math.random() * H) or (H + 12)
    end
end

local function setParticleTex()
    local def = partKind and KINDS[partKind]
    if not def then return end
    local u = Assets.tex[def.tex] or TX(def.tex)
    for i = 1, poolN do
        local p = pool[i]
        if p.f.Image ~= u then p.f.Image = u end
    end
end
Assets.watchers[#Assets.watchers + 1] = setParticleTex

function UIX.applyParticles()
    local pk = C("bgPart")
    if pk == "Theme default" then pk = T.theme and T.theme.part or nil end
    if pk == "Off" or not KINDS[pk or ""] then pk = nil end
    local n = pk and clamp(math.floor(tonumber(C("bgPartN")) or 12), 0, poolN) or 0
    if C("uiLite") then n = math.min(n, 6) end
    if pk ~= partKind then
        partKind = pk
        if pk then
            setParticleTex()
            for i = 1, poolN do respawn(pool[i], KINDS[pk], true) end
        end
    end
    partActive = n
    for i = 1, poolN do pool[i].f.Visible = (i <= n) end
end

local function partStep(t, dt)
    local def = partKind and KINDS[partKind]
    if not def or partActive == 0 then return end
    local W, H = DW, DH
    local n = partActive
    if UIX.perfTier >= 2 then n = math.max(2, math.floor(n / 2)) end
    for i = 1, n do
        local p = pool[i]
        local edge = 1
        if def.twinkle then
            p.life = p.life + dt
            if p.life >= p.max then respawn(p, def, false) end
            local u = p.life / p.max
            edge = math.sin(u * math.pi)
            p.y = p.y + p.vy * dt
            p.x = p.x + p.vx * dt
            if p.y < -10 then p.y = H + 10 elseif p.y > H + 10 then p.y = -10 end
        else
            p.x = p.x + (p.vx + math.sin(t * p.sw + p.ph) * def.sway) * dt
            p.y = p.y + p.vy * def.dir * dt
            p.rot = p.rot + p.vr * dt
            if p.y > H + 14 or p.y < -14 or p.x < -20 or p.x > W + 20 then respawn(p, def, false) end
            edge = clamp((p.y + 10) / 50, 0, 1) * clamp((H + 10 - p.y) / 50, 0, 1)
        end
        p.f.Position = UDim2.fromOffset(p.x, p.y)
        p.f.Rotation = p.rot
        p.f.ImageTransparency = 1 - edge * (1 - def.alpha)
    end
end

local function blobStep(t)
    local b1, b2 = blobs[1], blobs[2]
    b1.Position = UDim2.fromScale(0.15 + math.sin(t * 0.21) * 0.07, 0.12 + math.cos(t * 0.17) * 0.07)
    b2.Position = UDim2.fromScale(0.88 + math.cos(t * 0.19) * 0.06, 0.94 + math.sin(t * 0.23) * 0.06)
end

UIX.bgStep, UIX.partStep, UIX.blobStep = bgStep, partStep, blobStep
UIX.perfTier = 0
UIX.statusLbl, UIX.fpsLbl, UIX.topGrad, UIX.logoGrad, UIX.borderGrad = statusLbl, fpsLbl, topGrad, logoGrad, borderGrad
UIX.paintAllTabs = function(snap)
    for _, t in ipairs(tabs) do paintTab(t, snap) end
    for _, g in ipairs(groupList) do paintGroup(g, snap) end
end
UIX.bgImg, UIX.pool, UIX.top, UIX.sideList, UIX.crumbName, UIX.crumbGroup = bgImg, pool, top, sideList, crumbName, crumbGroup
end
do

local C, F, XL, XR, XC = UIX.C, UIX.F, UIX.XL, UIX.XR, UIX.XC
local TI, tw, new, corner, stroke, pad, vlist, WHITE = UIX.TI, UIX.tw, UIX.new, UIX.corner, UIX.stroke, UIX.pad, UIX.vlist, UIX.WHITE
local T, bindTheme, bindGrad, reg, label, icon, chevron = UIX.T, UIX.bindTheme, UIX.bindGrad, UIX.reg, UIX.label, UIX.icon, UIX.chevron
local isPress, curScale, root = UIX.isPress, UIX.curScale, UIX.root

UIX.sliderAnim = {}
local sliderAnim = UIX.sliderAnim

local ddCatcher
local function closeDD()
    local cbk = UIX.ddClosed
    if cbk then UIX.ddClosed = nil; pcall(cbk) end
    if ddCatcher then
        local c = ddCatcher
        ddCatcher = nil
        local box = c:FindFirstChildOfClass("Frame")
        if box then
            tw(box, TI.fast, { BackgroundTransparency = 1, Size = UDim2.new(0, box.Size.X.Offset, 0, 0) })
            task.delay(0.14, function() pcall(function() c:Destroy() end) end)
        else
            c:Destroy()
        end
    end
end
UIX.closeDD = closeDD

local function openDD(anchor, options, multi, getVal, pick)
    closeDD()
    local catcher = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 50, AutoButtonColor = false, BorderSizePixel = 0 }, root)
    ddCatcher = catcher
    catcher.Activated:Connect(closeDD)
    local n = #options
    local searchable = n > 14
    local rowH = 26
    local h = math.min(n * rowH + 10 + (searchable and 32 or 0), 270)
    local sc = curScale()
    local ap = anchor.AbsolutePosition - root.AbsolutePosition
    local asz = anchor.AbsoluteSize
    local y = ap.Y + asz.Y + 4
    if y + h * sc > root.AbsoluteSize.Y - 6 then y = math.max(4, ap.Y - h * sc - 4) end
    local width = math.max(asz.X / sc, 176)
    local box = new("Frame", {
        Position = UDim2.fromOffset(ap.X, y), Size = UDim2.fromOffset(width, 0), BackgroundColor3 = T.panel, BackgroundTransparency = 0.02, BorderSizePixel = 0,
        ClipsDescendants = true, ZIndex = 51,
    }, catcher)
    new("UIScale", { Scale = sc }, box)
    corner(box, 10)
    stroke(box, T.acc, 1.2, 0.4)
    local listTop = 0
    local query = ""
    if searchable then
        local sb = new("TextBox", {
            Size = UDim2.new(1, -14, 0, 26), Position = UDim2.fromOffset(7, 5), BackgroundColor3 = T.panel2, Text = "", PlaceholderText = "search...",
            TextColor3 = T.text, PlaceholderColor3 = T.dim, Font = F.reg, TextSize = 12, ClearTextOnFocus = false, TextXAlignment = XL, ZIndex = 53, BorderSizePixel = 0,
        }, box)
        corner(sb, 7); pad(sb, 8, 0, 8, 0)
        listTop = 34
        sb:GetPropertyChangedSignal("Text"):Connect(function() query = string.lower(sb.Text); box:SetAttribute("q", query) end)
    end
    local lst = new("ScrollingFrame", {
        Position = UDim2.fromOffset(0, listTop), Size = UDim2.new(1, 0, 1, -listTop), BackgroundTransparency = 1, BorderSizePixel = 0, ScrollBarThickness = 3,
        ScrollBarImageColor3 = T.acc, CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 52,
    }, box)
    pad(lst, 5, 5, 5, 5); vlist(lst, 0)
    local painters, rows = {}, {}
    for i, opt in ipairs(options) do
        local b = new("TextButton", { Size = UDim2.new(1, 0, 0, rowH), BackgroundColor3 = T.panel2, BackgroundTransparency = 1, Text = "", LayoutOrder = i, ZIndex = 52,
            AutoButtonColor = false, BorderSizePixel = 0 }, lst)
        corner(b, 7)
        local mark_ = new("Frame", { Size = UDim2.fromOffset(3, 0), AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 2, 0.5, 0), BackgroundColor3 = T.acc, BorderSizePixel = 0, ZIndex = 54 }, b)
        corner(mark_, 2)
        local tl = new("TextLabel", { BackgroundTransparency = 1, Text = opt, TextSize = 12, Font = F.reg, TextXAlignment = XL, TextColor3 = T.text, ZIndex = 53,
            Size = UDim2.new(1, -16, 1, 0), Position = UDim2.fromOffset(12, 0), TextTruncate = Enum.TextTruncate.AtEnd, BorderSizePixel = 0 }, b)
        local function paint()
            local cur = getVal()
            local sel
            if multi then sel = cur[opt] else sel = (cur == opt) end
            tw(tl, TI.fast, { TextColor3 = sel and T.acc or T.text })
            tl.Font = sel and F.bold or F.reg
            tw(mark_, TI.med, { Size = UDim2.fromOffset(3, sel and 14 or 0) })
            if multi then tl.Text = (sel and "+  " or "    ") .. opt end
        end
        painters[#painters + 1] = paint
        rows[i] = { b = b, opt = opt }
        paint()
        b.MouseEnter:Connect(function() tw(b, TI.fast, { BackgroundTransparency = 0.4 }) end)
        b.MouseLeave:Connect(function() tw(b, TI.fast, { BackgroundTransparency = 1 }) end)
        b.Activated:Connect(function()
            pick(opt)
            if multi then for _, p in ipairs(painters) do p() end else closeDD() end
        end)
    end
    if searchable then
        box:GetAttributeChangedSignal("q"):Connect(function()
            local q = box:GetAttribute("q") or ""
            for _, r in ipairs(rows) do
                r.b.Visible = (q == "") or (string.find(string.lower(r.opt), q, 1, true) ~= nil)
            end
        end)
    end
    tw(box, TI.med, { Size = UDim2.fromOffset(width, h) })
end

UIX.bindCtls = {}
local KEYL = {
    LeftShift = "LShift", RightShift = "RShift", LeftControl = "LCtrl", RightControl = "RCtrl", LeftAlt = "LAlt", RightAlt = "RAlt", Return = "Enter",
    Backquote = "`", BackSlash = "\\", One = "1", Two = "2", Three = "3", Four = "4", Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9", Zero = "0",
    LeftBracket = "[", RightBracket = "]", Semicolon = ";", Quote = "'", Comma = ",", Period = ".", Slash = "/", Minus = "-", Equals = "=",
    Backspace = "Bksp", Delete = "Del", Insert = "Ins", PageUp = "PgUp", PageDown = "PgDn", CapsLock = "Caps",
}
function UIX.keyLabel(n)
    n = tostring(n or "")
    return KEYL[n] or (n:gsub("^Keypad", "Num"))
end

local function bindOf(key)
    local b = cfg.binds and cfg.binds[key]
    if type(b) == "table" and b.k then return b end
    return nil
end

function UIX.refreshBinds()
    for _, c in ipairs(UIX.bindCtls) do
        if c.paintBind then c.paintBind() end
    end
    if UIX.onBinds then pcall(UIX.onBinds) end
end

function UIX.fireBind(kn, down)
    local bt = cfg.binds
    if type(bt) ~= "table" then return end
    for fk, b in pairs(bt) do
        if type(b) == "table" and b.k == kn then
            local f = Flags[fk]
            if f and f.kind == "toggle" and f.Set then
                if b.m == "Hold" then
                    f:Set(down)
                elseif down then
                    f:Set(not cfg[fk])
                    notify((f.text or fk) .. ": " .. (cfg[fk] and "on" or "off"), 1.2)
                end
            end
        end
    end
end

local function openBind(ctl)
    closeDD()
    local key = ctl.key
    if type(cfg.binds) ~= "table" then cfg.binds = {} end
    local catcher = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 50, AutoButtonColor = false, BorderSizePixel = 0 }, root)
    ddCatcher = catcher
    catcher.Activated:Connect(closeDD)
    local closed = false
    UIX.ddClosed = function()
        closed = true
        local l = UIX.listening
        if l then UIX.listening = nil; pcall(l, nil) end
    end
    local BW, BH = 236, 156
    local sc = curScale()
    local fa, fs = ctl.frame.AbsolutePosition - root.AbsolutePosition, ctl.frame.AbsoluteSize
    local x = math.max(6, math.min(fa.X + fs.X / 2 - BW * sc / 2, root.AbsoluteSize.X - BW * sc - 6))
    local y = fa.Y + fs.Y + 4
    if y + BH * sc > root.AbsoluteSize.Y - 6 then y = math.max(4, fa.Y - BH * sc - 4) end
    local box = new("Frame", {
        Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(BW, 0), BackgroundColor3 = T.panel, BackgroundTransparency = 0.02, BorderSizePixel = 0,
        ClipsDescendants = true, ZIndex = 51, Active = true,
    }, catcher)
    new("UIScale", { Scale = sc }, box)
    corner(box, 12)
    stroke(box, T.acc, 1.2, 0.35)
    local function txt(parent, text, size, font, col, x_, y_, w_, h_, xa)
        return new("TextLabel", { BackgroundTransparency = 1, Text = text, TextSize = size, Font = font, TextColor3 = col, TextXAlignment = xa or XL, TextTruncate = Enum.TextTruncate.AtEnd,
            Position = UDim2.fromOffset(x_, y_), Size = UDim2.fromOffset(w_, h_), ZIndex = 53, BorderSizePixel = 0 }, parent)
    end
    txt(box, ctl.text or key, 14, F.bold, T.text, 14, 10, BW - 28, 18)
    txt(box, ctl.where or "", 10, F.reg, T.dim, 14, 29, BW - 28, 14)
    new("Frame", { Size = UDim2.fromOffset(BW - 28, 1), Position = UDim2.fromOffset(14, 50), BackgroundColor3 = T.line, BackgroundTransparency = 0.4, BorderSizePixel = 0, ZIndex = 52 }, box)

    txt(box, "Key", 12, F.med, T.text, 14, 60, 70, 26)
    local kb = new("TextButton", { Position = UDim2.fromOffset(BW - 142, 60), Size = UDim2.fromOffset(128, 26), BackgroundColor3 = T.off, Text = "", AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 52 }, box)
    corner(kb, 8)
    local kst = stroke(kb, T.line, 1, 0.3)
    local kl = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Font = F.bold, TextSize = 12, TextColor3 = T.text, ZIndex = 53, BorderSizePixel = 0, Text = "" }, kb)
    local capturing = false
    local pendingMode = "Toggle"
    local function paintKey()
        if closed then return end
        local b = bindOf(key)
        kl.Text = capturing and "press a key..." or (b and UIX.keyLabel(b.k) or "None")
        kl.TextColor3 = capturing and T.acc or (b and T.text or T.dim)
        tw(kst, TI.fast, { Color = capturing and T.acc or T.line })
    end

    txt(box, "Mode", 12, F.med, T.text, 14, 94, 70, 26)
    local seg = new("Frame", { Position = UDim2.fromOffset(BW - 142, 94), Size = UDim2.fromOffset(128, 26), BackgroundColor3 = T.off, BorderSizePixel = 0, ZIndex = 52, ClipsDescendants = true }, box)
    corner(seg, 8)
    local hl = new("Frame", { Size = UDim2.new(0.5, -4, 1, -4), Position = UDim2.fromOffset(2, 2), BackgroundColor3 = T.acc, BorderSizePixel = 0, ZIndex = 53 }, seg)
    corner(hl, 6)
    local modeBtns = {}
    local function paintMode()
        if closed then return end
        local b = bindOf(key)
        local m = b and b.m or pendingMode
        local idx = (m == "Hold") and 2 or 1
        tw(hl, TI.back, { Position = UDim2.new((idx - 1) * 0.5, 2, 0, 2) })
        for i, mb in ipairs(modeBtns) do tw(mb, TI.fast, { TextColor3 = (i == idx) and T.onacc or T.dim }) end
    end
    for i, m in ipairs({ "Toggle", "Hold" }) do
        local mb = new("TextButton", { Size = UDim2.new(0.5, 0, 1, 0), Position = UDim2.new((i - 1) * 0.5, 0, 0, 0), BackgroundTransparency = 1, Text = m, TextSize = 11, Font = F.bold,
            TextColor3 = T.dim, AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 54 }, seg)
        modeBtns[i] = mb
        mb.Activated:Connect(function()
            local b = bindOf(key)
            if b then b.m = m else pendingMode = m end
            paintMode()
            UIX.refreshBinds()
        end)
    end

    txt(box, "Esc cancels  |  Backspace clears", 10, F.reg, T.dim, 14, 130, BW - 100, 16)
    local clr = new("TextButton", { Position = UDim2.fromOffset(BW - 70, 126), Size = UDim2.fromOffset(56, 22), BackgroundColor3 = T.off, Text = "Clear", TextSize = 11, Font = F.bold,
        TextColor3 = T.dim, AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 52 }, box)
    corner(clr, 7)
    clr.Activated:Connect(function()
        cfg.binds[key] = nil
        capturing = false
        paintKey(); paintMode()
        UIX.refreshBinds()
    end)

    kb.Activated:Connect(function()
        capturing = true
        paintKey()
        UIX.listening = function(name)
            capturing = false
            if name ~= nil then
                if name == "Backspace" or name == "Delete" then
                    cfg.binds[key] = nil
                elseif name == cfg.menuKey then
                    notify("That key opens the menu - pick another one", 2.5)
                else
                    local old = bindOf(key)
                    cfg.binds[key] = { k = name, m = old and old.m or pendingMode }
                end
                UIX.refreshBinds()
            end
            paintKey(); paintMode()
        end
    end)
    paintKey(); paintMode()
    UIX._bindWin = { box = box, kb = kb, clr = clr, modeBtns = modeBtns, catcher = catcher }
    tw(box, TI.med, { Size = UDim2.fromOffset(BW, BH) })
end
UIX.openBind = openBind

local Sec = {}
Sec.__index = Sec
UIX.Sec = Sec

function Sec:_row(h)
    self.n = self.n + 1
    local f = new("Frame", { Size = UDim2.new(1, 0, 0, h), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = self.n }, self.body)
    bindTheme(f, "BackgroundColor3", "panel2")
    corner(f, 8)
    f.MouseEnter:Connect(function() tw(f, TI.fast, { BackgroundTransparency = 0.6 }) end)
    f.MouseLeave:Connect(function() tw(f, TI.fast, { BackgroundTransparency = 1 }) end)
    return f
end

function Sec:Label(text)
    self.n = self.n + 1
    local l = label(self.body, text, 11, "dim", F.reg, XL)
    l.Size = UDim2.new(1, 0, 0, 0); l.AutomaticSize = Enum.AutomaticSize.Y; l.TextWrapped = true; l.LayoutOrder = self.n
    return l
end

function Sec:Custom(h)
    self.n = self.n + 1
    local f = new("Frame", { Size = UDim2.new(1, 0, 0, h), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = self.n, ClipsDescendants = true }, self.body)
    corner(f, 10)
    return f
end

function Sec:Divider(text)
    self.n = self.n + 1
    local f = new("Frame", { Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, LayoutOrder = self.n, BorderSizePixel = 0 }, self.body)
    local l = label(f, string.upper(text), 10, "acc", F.bold, XL)
    l.Size = UDim2.new(1, 0, 1, 0); l.Position = UDim2.fromOffset(8, 2)
    return l
end

function Sec:Toggle(key, text, default, onChange)
    local f = self:_row(30)
    local lbl = label(f, text, 13, "text", F.med, XL)
    lbl.Size = UDim2.new(1, -62, 1, 0); lbl.Position = UDim2.fromOffset(8, 0); lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local track = new("Frame", { Size = UDim2.fromOffset(38, 20), Position = UDim2.new(1, -46, 0.5, -10), BorderSizePixel = 0 }, f)
    corner(track, 10); bindTheme(track, "BackgroundColor3", "off")
    local fillOn = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0 }, track)
    corner(fillOn, 10); bindGrad(new("UIGradient", {}, fillOn), "lin")
    local knob = new("Frame", { Size = UDim2.fromOffset(14, 14), Position = UDim2.fromOffset(3, 3), BorderSizePixel = 0, BackgroundColor3 = T.dim }, track)
    corner(knob, 7)
    local chip = new("Frame", { AnchorPoint = Vector2.new(1, 0.5), Size = UDim2.fromOffset(30, 16), Position = UDim2.new(1, -52, 0.5, 0), BackgroundTransparency = 0.82,
        BorderSizePixel = 0, Visible = false }, f)
    corner(chip, 5); bindTheme(chip, "BackgroundColor3", "acc")
    local chipTxt = new("TextLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Text = "", TextSize = 10, Font = F.bold, BorderSizePixel = 0 }, chip)
    bindTheme(chipTxt, "TextColor3", "acc")
    local nameBtn = new("TextButton", { Size = UDim2.new(1, -90, 1, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0 }, f)
    local btn = new("TextButton", { Size = UDim2.fromOffset(90, 30), Position = UDim2.new(1, -90, 0, 0), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0 }, f)
    local ctl = { kind = "toggle", frame = f, key = key, text = text, chipRight = 52 }
    ctl.where = (self.tab and self.tab.name or "") .. ((self.title and self.title ~= "") and ("  |  " .. self.title) or "")
    local grp = self.grp
    cfg[key] = default
    Flags[key] = ctl
    local first = true
    local function render(snap)
        local on = cfg[key] == true
        local fp = { BackgroundTransparency = on and 0 or 1 }
        local kp = { Position = on and UDim2.fromOffset(21, 3) or UDim2.fromOffset(3, 3), BackgroundColor3 = on and WHITE or T.dim }
        local lp_ = { TextColor3 = on and T.text or T.dim }
        if first or snap == true then
            first = false
            for k, v in pairs(fp) do fillOn[k] = v end
            for k, v in pairs(kp) do knob[k] = v end
            for k, v in pairs(lp_) do lbl[k] = v end
        else
            tw(fillOn, TI.med, fp)
            tw(knob, TI.back, kp)
            tw(lbl, TI.fast, lp_)
        end
    end
    reg(render)
    function ctl.paintBind()
        local b = bindOf(key)
        if b then
            local t_ = UIX.keyLabel(b.k) .. (b.m == "Hold" and " hold" or "")
            chipTxt.Text = t_
            local w = 12 + #t_ * 6
            chip.Size = UDim2.fromOffset(w, 16)
            chip.Position = UDim2.new(1, -ctl.chipRight, 0.5, 0)
            chip.Visible = true
            lbl.Size = UDim2.new(1, -(ctl.chipRight + w + 10), 1, 0)
        else
            chip.Visible = false
            lbl.Size = UDim2.new(1, -(ctl.chipRight + 10), 1, 0)
        end
    end
    UIX.bindCtls[#UIX.bindCtls + 1] = ctl
    function ctl:Set(v, silent)
        cfg[key] = v and true or false
        render()
        if not silent then
            mark(grp)
            if onChange then onChange(cfg[key]) end
        end
    end
    btn.Activated:Connect(function() ctl:Set(not cfg[key]) end)
    nameBtn.Activated:Connect(function()
        if cfg.bindClick ~= false then openBind(ctl) else ctl:Set(not cfg[key]) end
    end)
    render(true)
    ctl.paintBind()
    UIX.indexCtl(self, text, f)
    return ctl
end

function Sec:Group(key, text, default, onChange)
    local ctl = self:Toggle(key, text, default, onChange)
    local more = new("TextButton", { Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromOffset(28, 28), Position = UDim2.new(1, -82, 0, 1), BorderSizePixel = 0 }, ctl.frame)
    ctl.chipRight = 90
    ctl.paintBind()
    local chev = chevron(more, "dim", 12)
    chev.Position = UDim2.fromScale(0.5, 0.5)
    self.n = self.n + 1
    local holder = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), ClipsDescendants = true, LayoutOrder = self.n, BorderSizePixel = 0 }, self.body)
    local lineV = new("Frame", { Size = UDim2.new(0, 2, 1, -6), Position = UDim2.fromOffset(5, 2), BorderSizePixel = 0, BackgroundTransparency = 0.3 }, holder)
    corner(lineV, 1); bindTheme(lineV, "BackgroundColor3", "line")
    local inner = new("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BorderSizePixel = 0 }, holder)
    vlist(inner, 4); pad(inner, 14, 2, 0, 6)
    local open, busy = false, 0
    local function targetH() return math.floor(inner.AbsoluteSize.Y / curScale() + 0.5) end
    inner:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
        if open and busy == 0 then holder.Size = UDim2.new(1, 0, 0, targetH()) end
    end)
    local function setOpen(v)
        if open == v then return end
        open = v
        busy = busy + 1
        local my = busy
        tw(chev, TI.back, { Rotation = open and 180 or 0 })
        tw(holder, TI.med, { Size = UDim2.new(1, 0, 0, open and targetH() or 0) })
        task.delay(0.26, function()
            if busy == my then
                busy = 0
                if open then holder.Size = UDim2.new(1, 0, 0, targetH()) end
            end
        end)
    end
    more.Activated:Connect(function() setOpen(not open) end)
    local parentReveal = self.reveal
    local sub = setmetatable({ body = inner, grp = self.grp, n = 0, tab = self.tab, title = self.title,
        reveal = function() if parentReveal then parentReveal() end; setOpen(true) end }, Sec)
    return sub, ctl
end

function Sec:Slider(key, text, min, max, default, dec, suffix, onChange)
    dec = dec or 0
    local f = self:_row(40)
    local nm = label(f, text, 12, "text", F.med, XL)
    nm.Size = UDim2.new(1, -86, 0, 18); nm.Position = UDim2.fromOffset(8, 3)
    local vl = label(f, "", 12, "dim", F.bold, XR)
    vl.Size = UDim2.fromOffset(80, 18); vl.Position = UDim2.new(1, -88, 0, 3)
    local track = new("Frame", { Size = UDim2.new(1, -20, 0, 6), Position = UDim2.fromOffset(10, 28), BorderSizePixel = 0 }, f)
    corner(track, 3); bindTheme(track, "BackgroundColor3", "off")
    local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0, BackgroundColor3 = WHITE }, track)
    corner(fill, 3); bindGrad(new("UIGradient", {}, fill), "lin")
    local knob = new("Frame", { Size = UDim2.fromOffset(13, 13), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 2 }, track)
    corner(knob, 7)
    local kst = stroke(knob, T.acc, 2, 0)
    bindTheme(kst, "Color", "acc")
    local hit = new("TextButton", { Size = UDim2.new(1, 0, 0, 28), Position = UDim2.fromOffset(0, 12), BackgroundTransparency = 1, Text = "", AutoButtonColor = false, BorderSizePixel = 0 }, f)
    local ctl = { kind = "slider", track = track, fill = fill, knob = knob, frame = f, vis = 0, tgt = 0, min = min, max = max }
    local grp = self.grp
    cfg[key] = default
    Flags[key] = ctl
    local fmt = "%." .. dec .. "f"
    local function ratio() return (cfg[key] - min) / (max - min) end
    local function paint()
        local r = clamp(ctl.vis, 0, 1)
        fill.Size = UDim2.fromScale(r, 1)
        knob.Position = UDim2.fromScale(r, 0.5)
        if ctl.onPaint then ctl.onPaint(cfg[key]) end
    end
    local function render(snap)
        ctl.tgt = ratio()
        vl.Text = string.format(fmt, cfg[key]) .. (suffix or "")
        if snap or not UIX.shell.Visible then ctl.vis = ctl.tgt; paint() else sliderAnim[ctl] = true end
    end
    ctl.paint = paint
    reg(function() paint() end)
    function ctl:Set(v, silent)
        v = clamp(tonumber(v) or min, min, max)
        local stp = 10 ^ (-dec)
        v = math.floor(v / stp + 0.5) * stp
        cfg[key] = v
        render(false)
        if not silent then
            mark(grp)
            if onChange then onChange(v) end
        end
    end
    local function fromX(x)
        local r = clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
        ctl:Set(min + (max - min) * r)
    end
    hit.InputBegan:Connect(function(i)
        if isPress(i) then
            closeDD()
            local sc = f:FindFirstAncestorWhichIsA("ScrollingFrame")
            if sc then sc.ScrollingEnabled = false; UIX.drag.lock = sc end
            tw(knob, TI.fast, { Size = UDim2.fromOffset(18, 18) })
            tw(vl, TI.fast, { TextColor3 = T.acc })
            UIX.drag.fn = function(m) fromX(m.Position.X) end
            UIX.dragEnd = function()
                tw(knob, TI.back, { Size = UDim2.fromOffset(13, 13) })
                tw(vl, TI.med, { TextColor3 = T.dim })
            end
            fromX(i.Position.X)
        end
    end)
    render(true)
    UIX.indexCtl(self, text, f)
    return ctl
end

function Sec:Hue(key, text, default, onChange)
    local ctl = self:Slider(key, text, 0, 360, default, 0, " deg", onChange)
    ctl.track.BackgroundColor3 = WHITE
    local ks = {}
    for i = 0, 6 do ks[#ks + 1] = CK(i / 6, Color3.fromHSV((i % 6) / 6, 0.95, 1)) end
    new("UIGradient", { Color = ColorSequence.new(ks) }, ctl.track)
    ctl.fill.BackgroundTransparency = 1
    for _, c in ipairs(ctl.fill:GetChildren()) do if c:IsA("UIGradient") then c.Enabled = false end end
    ctl.onPaint = function(v) ctl.knob.BackgroundColor3 = hsv(v, 0.75, 1) end
    reg(function() ctl.track.BackgroundColor3 = WHITE end)
    ctl.paint()
    return ctl
end

function Sec:Segment(key, text, options, default, onChange)
    local f = self:_row(30)
    local lbl = label(f, text, 12, "text", F.med, XL)
    lbl.Size = UDim2.new(0.36, 0, 1, 0); lbl.Position = UDim2.fromOffset(8, 0); lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local box = new("Frame", { Size = UDim2.new(0.64, -8, 0, 24), Position = UDim2.new(0.36, 0, 0.5, -12), BorderSizePixel = 0, ClipsDescendants = true }, f)
    corner(box, 8); bindTheme(box, "BackgroundColor3", "off")
    local n = #options
    local hl = new("Frame", { Size = UDim2.new(1 / n, -4, 1, -4), Position = UDim2.new(0, 2, 0, 2), BackgroundColor3 = WHITE, BorderSizePixel = 0 }, box)
    corner(hl, 6); bindGrad(new("UIGradient", {}, hl), "lin")
    local btns = {}
    local ctl = { kind = "segment", options = options, frame = f }
    local grp = self.grp
    cfg[key] = default
    Flags[key] = ctl
    local first = true
    local function render(snap)
        local idx = 1
        for i, o in ipairs(options) do if o == cfg[key] then idx = i end end
        local pos = UDim2.new((idx - 1) / n, 2, 0, 2)
        if first or snap == true then first = false; hl.Position = pos else tw(hl, TI.back, { Position = pos }) end
        for i, b in ipairs(btns) do
            local on = (i == idx)
            local col = on and T.onacc or T.dim
            if snap == true then b.TextColor3 = col else tw(b, TI.fast, { TextColor3 = col }) end
        end
    end
    reg(render)
    for i, o in ipairs(options) do
        local b = new("TextButton", { Size = UDim2.new(1 / n, 0, 1, 0), Position = UDim2.new((i - 1) / n, 0, 0, 0), BackgroundTransparency = 1, Text = o, TextSize = 11,
            Font = F.bold, TextColor3 = T.dim, AutoButtonColor = false, BorderSizePixel = 0, TextTruncate = Enum.TextTruncate.AtEnd }, box)
        btns[i] = b
        b.Activated:Connect(function() ctl:Set(o) end)
    end
    function ctl:Set(v, silent)
        cfg[key] = v
        render()
        if not silent then
            mark(grp)
            if onChange then onChange(v) end
        end
    end
    render(true)
    UIX.indexCtl(self, text, f)
    return ctl
end

function Sec:Dropdown(key, text, options, default, multi, onChange)
    local f = self:_row(30)
    local lbl = label(f, text, 12, "text", F.med, XL)
    lbl.Size = UDim2.new(0.36, 0, 1, 0); lbl.Position = UDim2.fromOffset(8, 0); lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local box = new("TextButton", { Size = UDim2.new(0.64, -8, 0, 24), Position = UDim2.new(0.36, 0, 0.5, -12), Text = "", AutoButtonColor = false, BorderSizePixel = 0,
        ClipsDescendants = true }, f)
    corner(box, 8); bindTheme(box, "BackgroundColor3", "off")
    local bst = stroke(box, T.line, 1, 0.3)
    bindTheme(bst, "Color", "line")
    local val = label(box, "", 12, "text", F.reg, XL)
    val.Size = UDim2.new(1, -28, 1, 0); val.Position = UDim2.fromOffset(9, 0); val.TextTruncate = Enum.TextTruncate.AtEnd
    local arr = chevron(box, "dim", 10)
    arr.Position = UDim2.new(1, -13, 0.5, 0)
    box.MouseEnter:Connect(function() tw(bst, TI.fast, { Color = T.acc }) end)
    box.MouseLeave:Connect(function() tw(bst, TI.fast, { Color = T.line }) end)
    box.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(box, i.Position, "acc") end end)
    local ctl = { kind = "dropdown", options = options, frame = f }
    local grp = self.grp
    if multi then cfg[key] = copyT(default) else cfg[key] = default end
    Flags[key] = ctl
    local function txt()
        if multi then
            local parts = {}
            for _, o in ipairs(ctl.options) do if cfg[key][o] then parts[#parts + 1] = o end end
            return #parts > 0 and table.concat(parts, ", ") or "None"
        end
        return tostring(cfg[key])
    end
    function ctl:Set(v, silent)
        if multi then
            local nt = {}
            if type(v) == "table" then for k, x in pairs(v) do nt[k] = x and true or false end end
            cfg[key] = nt
        else
            cfg[key] = v
        end
        val.Text = txt()
        if not silent then
            mark(grp)
            if onChange then onChange(cfg[key]) end
        end
    end
    function ctl:SetOptions(o) ctl.options = o; val.Text = txt() end
    box.Activated:Connect(function()
        tw(arr, TI.back, { Rotation = 180 })
        openDD(box, ctl.options, multi, function() return cfg[key] end, function(opt)
            if multi then
                cfg[key][opt] = not cfg[key][opt]
                val.Text = txt()
                mark(grp)
                if onChange then onChange(cfg[key]) end
            else
                ctl:Set(opt)
            end
        end)
        UIX.ddClosed = function() tw(arr, TI.med, { Rotation = 0 }) end
    end)
    val.Text = txt()
    UIX.indexCtl(self, text, f)
    return ctl
end

function Sec:Button(text, cb, primary)
    local f = self:_row(32)
    local b = new("TextButton", { Size = UDim2.new(1, 0, 0, 28), Position = UDim2.fromOffset(0, 2), Text = text, TextSize = 12, Font = F.bold, AutoButtonColor = false,
        BorderSizePixel = 0, ClipsDescendants = true }, f)
    corner(b, 8)
    local bst = stroke(b, T.line, 1, 0.2)
    bindTheme(bst, "Color", "line")
    if primary then
        b.BackgroundColor3 = WHITE
        bindGrad(new("UIGradient", {}, b), "lin")
        bindTheme(b, "TextColor3", "onacc")
        bst.Transparency = 1
    else
        bindTheme(b, "BackgroundColor3", "off")
        bindTheme(b, "TextColor3", "text")
    end
    b.MouseEnter:Connect(function()
        if not primary then tw(b, TI.fast, { BackgroundColor3 = T.panel2 }) end
        tw(bst, TI.fast, { Color = T.acc })
    end)
    b.MouseLeave:Connect(function()
        if not primary then tw(b, TI.fast, { BackgroundColor3 = T.off }) end
        tw(bst, TI.fast, { Color = T.line })
    end)
    b.InputBegan:Connect(function(i) if isPress(i) then UIX.ripple(b, i.Position, primary and "text" or "acc") end end)
    b.Activated:Connect(function()
        local ok, e = pcall(cb)
        if not ok then report("button", e) end
    end)
    UIX.indexCtl(self, text, f)
    return b
end

function Sec:TextBox(key, text, placeholder, default, onSubmit)
    local f = self:_row(30)
    local lbl = label(f, text, 12, "text", F.med, XL)
    lbl.Size = UDim2.new(0.3, 0, 1, 0); lbl.Position = UDim2.fromOffset(8, 0); lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local tb = new("TextBox", {
        Size = UDim2.new(0.7, -8, 0, 24), Position = UDim2.new(0.3, 0, 0.5, -12), Text = default or "", PlaceholderText = placeholder or "", Font = F.reg, TextSize = 12,
        ClearTextOnFocus = false, TextXAlignment = XL, BorderSizePixel = 0,
    }, f)
    bindTheme(tb, "BackgroundColor3", "off"); bindTheme(tb, "TextColor3", "text"); bindTheme(tb, "PlaceholderColor3", "dim")
    corner(tb, 8); pad(tb, 9, 0, 9, 0)
    local tst = stroke(tb, T.line, 1, 0.3)
    bindTheme(tst, "Color", "line")
    cfg[key] = default or ""
    local ctl = { kind = "text", frame = f }
    function ctl:Set(v) tb.Text = tostring(v); cfg[key] = tostring(v) end
    Flags[key] = ctl
    tb.Focused:Connect(function() tw(tst, TI.fast, { Color = T.acc, Transparency = 0 }) end)
    tb.FocusLost:Connect(function(enter)
        tw(tst, TI.fast, { Color = T.line, Transparency = 0.3 })
        cfg[key] = tb.Text
        if onSubmit then onSubmit(tb.Text, enter) end
    end)
    UIX.indexCtl(self, text, f)
    return tb
end

function Sec:Keybind(key, text, default, onChange)
    local f = self:_row(30)
    local lbl = label(f, text, 12, "text", F.med, XL)
    lbl.Size = UDim2.new(0.5, 0, 1, 0); lbl.Position = UDim2.fromOffset(8, 0)
    local b = new("TextButton", { Size = UDim2.new(0.5, -8, 0, 24), Position = UDim2.new(0.5, 0, 0.5, -12), Text = default, TextSize = 12, Font = F.bold, AutoButtonColor = false,
        BorderSizePixel = 0, ClipsDescendants = true }, f)
    corner(b, 8); bindTheme(b, "BackgroundColor3", "off"); bindTheme(b, "TextColor3", "text")
    local bst = stroke(b, T.line, 1, 0.3)
    bindTheme(bst, "Color", "line")
    cfg[key] = default
    local ctl = { kind = "key" }
    function ctl:Set(v)
        cfg[key] = v; b.Text = v
        tw(bst, TI.med, { Color = T.line })
        if onChange then onChange(v) end
    end
    Flags[key] = ctl
    b.Activated:Connect(function()
        b.Text = "press a key..."
        tw(bst, TI.fast, { Color = T.acc })
        UIX.listening = function(name) if name then ctl:Set(name) else b.Text = cfg[key]; tw(bst, TI.med, { Color = T.line }) end end
    end)
    UIX.indexCtl(self, text, f)
    return ctl
end

function Sec:BindList()
    self.n = self.n + 1
    local f = new("Frame", { Size = UDim2.new(1, 0, 0, 40), BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = self.n }, self.body)
    vlist(f, 3)
    local function rebuild()
        for _, c in ipairs(f:GetChildren()) do
            if c:IsA("GuiObject") then c:Destroy() end
        end
        local rows = {}
        for _, c in ipairs(UIX.bindCtls) do
            local b = bindOf(c.key)
            if b then rows[#rows + 1] = { c = c, b = b } end
        end
        table.sort(rows, function(a, b) return (a.c.where .. a.c.text) < (b.c.where .. b.c.text) end)
        local rowH = 32
        if #rows == 0 then
            local l = label(f, "No binds yet. Click the name of any switch and press a key.", 11, "dim", F.reg, XL)
            l.Size = UDim2.new(1, 0, 0, 34); l.TextWrapped = true; l.LayoutOrder = 1
            f.Size = UDim2.new(1, 0, 0, 40)
            return
        end
        f.Size = UDim2.new(1, 0, 0, #rows * (rowH + 3))
        for i, r in ipairs(rows) do
            local row = new("Frame", { Size = UDim2.new(1, 0, 0, rowH), BackgroundTransparency = 0.55, BorderSizePixel = 0, LayoutOrder = i }, f)
            bindTheme(row, "BackgroundColor3", "panel2"); corner(row, 8)
            local nm = label(row, r.c.text, 12, "text", F.med, XL)
            nm.Size = UDim2.new(1, -118, 0, 16); nm.Position = UDim2.fromOffset(8, 3); nm.TextTruncate = Enum.TextTruncate.AtEnd
            local wh = label(row, r.c.where, 9, "dim", F.reg, XL)
            wh.Size = UDim2.new(1, -118, 0, 12); wh.Position = UDim2.fromOffset(8, 18); wh.TextTruncate = Enum.TextTruncate.AtEnd
            local kb = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Size = UDim2.fromOffset(74, 22), Position = UDim2.new(1, -32, 0.5, 0), BackgroundTransparency = 0.82,
                Text = UIX.keyLabel(r.b.k) .. (r.b.m == "Hold" and "  hold" or ""), TextSize = 11, Font = F.bold, AutoButtonColor = false, BorderSizePixel = 0 }, row)
            corner(kb, 6); bindTheme(kb, "BackgroundColor3", "acc"); bindTheme(kb, "TextColor3", "acc")
            kb.Activated:Connect(function() openBind(r.c) end)
            local x = new("TextButton", { AnchorPoint = Vector2.new(1, 0.5), Size = UDim2.fromOffset(22, 22), Position = UDim2.new(1, -6, 0.5, 0), BackgroundTransparency = 1, Text = "x",
                TextSize = 13, Font = F.bold, AutoButtonColor = false, BorderSizePixel = 0 }, row)
            bindTheme(x, "TextColor3", "dim")
            x.Activated:Connect(function()
                cfg.binds[r.c.key] = nil
                UIX.refreshBinds()
            end)
        end
    end
    UIX.onBinds = rebuild
    UIX._bindList = f
    rebuild()
    return f
end

function Sec:ThemeGrid()
    self.n = self.n + 1
    local holder = new("Frame", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, LayoutOrder = self.n, BorderSizePixel = 0 }, self.body)
    new("UIGridLayout", { CellSize = UDim2.new(0.5, -4, 0, 70), CellPadding = UDim2.fromOffset(8, 8), SortOrder = Enum.SortOrder.LayoutOrder }, holder)
    local cards = {}
    local ctl = { kind = "themes", frame = holder }
    Flags.theme = ctl
    local function paintAll(snap)
        for name, c in pairs(cards) do
            local on = (C("theme") == name)
            local props = { Thickness = on and 2.5 or 1.5, Color = on and T.acc or c.th.line }
            if snap == true then for k, v in pairs(props) do c.st[k] = v end else tw(c.st, TI.med, props) end
            local tk = { BackgroundTransparency = on and 0 or 1 }
            if snap == true then c.tick.BackgroundTransparency = tk.BackgroundTransparency else tw(c.tick, TI.back, tk) end
            c.tickIn.Visible = on
        end
    end
    reg(paintAll)
    function ctl:Set(v, silent)
        if not UIX.THEMES[v] then return end
        cfg.theme = v
        paintAll()
        if not silent then mark("ui") end
    end
    for i, name in ipairs(UIX.THEME_ORDER) do
        local th = UIX.THEMES[name]
        local card = new("TextButton", { BackgroundColor3 = th.bg, Text = "", AutoButtonColor = false, LayoutOrder = i, BorderSizePixel = 0, ClipsDescendants = true }, holder)
        corner(card, 11)
        local cst = stroke(card, th.line, 1.5, 0)
        local strip = new("Frame", { Size = UDim2.new(1, -16, 0, 28), Position = UDim2.fromOffset(8, 8), BackgroundColor3 = WHITE, BorderSizePixel = 0 }, card)
        corner(strip, 8)
        new("UIGradient", { Color = ColorSequence.new({ CK(0, th.acc), CK(0.5, th.acc2), CK(1, th.acc3) }) }, strip)
        local sheen = new("Frame", { Size = UDim2.new(1, 0, 0.5, 0), BackgroundColor3 = WHITE, BackgroundTransparency = 0.82, BorderSizePixel = 0 }, strip)
        corner(sheen, 8)
        local tick = new("Frame", { Size = UDim2.fromOffset(16, 16), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0 }, strip)
        corner(tick, 8)
        local tickIn = new("Frame", { Size = UDim2.fromOffset(6, 6), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), BackgroundColor3 = th.acc, BorderSizePixel = 0, Visible = false }, tick)
        corner(tickIn, 3)
        local nm = new("TextLabel", { BackgroundTransparency = 1, Text = name, TextSize = 12, Font = F.bold, TextXAlignment = XL, TextColor3 = th.text,
            Position = UDim2.fromOffset(10, 41), Size = UDim2.new(1, -20, 0, 14), BorderSizePixel = 0 }, card)
        local nt = new("TextLabel", { BackgroundTransparency = 1, Text = th.note or "", TextSize = 10, Font = F.reg, TextXAlignment = XL, TextColor3 = th.dim,
            Position = UDim2.fromOffset(10, 54), Size = UDim2.new(1, -20, 0, 12), BorderSizePixel = 0, TextTruncate = Enum.TextTruncate.AtEnd }, card)
        cards[name] = { th = th, st = cst, tick = tick, tickIn = tickIn }
        card.MouseEnter:Connect(function() if C("theme") ~= name then tw(cst, TI.fast, { Color = th.acc }) end end)
        card.MouseLeave:Connect(function() if C("theme") ~= name then tw(cst, TI.fast, { Color = th.line }) end end)
        card.InputBegan:Connect(function(inp)
            if isPress(inp) then
                UIX.inkOrigin = { x = inp.Position.X, y = inp.Position.Y, t = os.clock() }
                UIX.ripple(card, inp.Position, "acc")
            end
        end)
        card.Activated:Connect(function()
            if cfg.theme ~= name then ctl:Set(name) end
        end)
    end
    paintAll(true)
    UIX.indexCtl(self, "Menu theme", holder)
    return ctl
end
end
do

local C, F, XL, XR, XC = UIX.C, UIX.F, UIX.XL, UIX.XR, UIX.XC
local TI, tw, new, corner, stroke, pad, vlist, WHITE = UIX.TI, UIX.tw, UIX.new, UIX.corner, UIX.stroke, UIX.pad, UIX.vlist, UIX.WHITE
local T, bindTheme, bindGrad, reg, label = UIX.T, UIX.bindTheme, UIX.bindGrad, UIX.reg, UIX.label
local isPress, isMove, curScale, gui, shell, win, viewport = UIX.isPress, UIX.isMove, UIX.curScale, UIX.gui, UIX.shell, UIX.win, UIX.viewport
local sliderAnim = UIX.sliderAnim
local menuOpen = false

local notifHolder = new("Frame", { Size = UDim2.new(0, 380, 0, 260), Position = UDim2.new(0.5, -190, 0, 14), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 90 }, gui)
new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 6), HorizontalAlignment = Enum.HorizontalAlignment.Center }, notifHolder)
local notifScale = new("UIScale", { Scale = 1 }, notifHolder)
local notifN, toasts = 0, {}
function UI.notify(text, dur)
    dur = dur or 3
    notifN = notifN + 1
    local slot = new("Frame", { Size = UDim2.new(0, 0, 0, 34), AutomaticSize = Enum.AutomaticSize.X, BackgroundTransparency = 1, LayoutOrder = notifN, BorderSizePixel = 0 }, notifHolder)
    local f = new("Frame", { Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = T.panel, BackgroundTransparency = 1, BorderSizePixel = 0,
        Position = UDim2.fromOffset(0, -18), ClipsDescendants = true }, slot)
    corner(f, 10)
    local st = stroke(f, T.line, 1, 1)
    pad(f, 18, 0, 14, 0)
    local stripe = new("Frame", { Size = UDim2.new(0, 4, 1, 0), Position = UDim2.fromOffset(-18, 0), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0 }, f)
    new("UIGradient", { Rotation = 90, Color = UIX.seqFor("lin") }, stripe)
    local l = new("TextLabel", { BackgroundTransparency = 1, Text = text, TextSize = 12, Font = F.med, TextColor3 = T.text, TextXAlignment = XL, TextTransparency = 1,
        Size = UDim2.new(0, 0, 1, 0), AutomaticSize = Enum.AutomaticSize.X, BorderSizePixel = 0 }, f)
    local barF = new("Frame", { Size = UDim2.new(1, 32, 0, 2), Position = UDim2.new(0, -18, 1, -2), BackgroundColor3 = WHITE, BackgroundTransparency = 1, BorderSizePixel = 0 }, f)
    new("UIGradient", { Color = UIX.seqFor("lin") }, barF)
    tw(f, TI.back, { Position = UDim2.fromOffset(0, 0), BackgroundTransparency = 0.04 })
    tw(st, TI.med, { Transparency = 0.1 })
    tw(l, TI.med, { TextTransparency = 0 })
    tw(stripe, TI.med, { BackgroundTransparency = 0 })
    tw(barF, TI.med, { BackgroundTransparency = 0.25 })
    tw(barF, TweenInfo.new(dur, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 2) })
    local rec = { slot = slot, gone = false }
    local function leave()
        if rec.gone then return end
        rec.gone = true
        pcall(function()
            tw(f, TI.med, { BackgroundTransparency = 1, Position = UDim2.fromOffset(0, -12) })
            tw(st, TI.med, { Transparency = 1 })
            tw(l, TI.med, { TextTransparency = 1 })
            tw(stripe, TI.med, { BackgroundTransparency = 1 })
            tw(barF, TI.med, { BackgroundTransparency = 1 })
        end)
        task.delay(0.3, function() pcall(function() slot:Destroy() end) end)
    end
    toasts[#toasts + 1] = rec
    rec.leave = leave
    task.delay(dur, leave)
    local live = 0
    for i = #toasts, 1, -1 do
        if toasts[i].gone then table.remove(toasts, i) else live = live + 1 end
    end
    if live > 4 then
        for _, r in ipairs(toasts) do
            if not r.gone then r.leave(); break end
        end
    end
end

local wm = new("Frame", { Size = UDim2.fromOffset(0, 28), AutomaticSize = Enum.AutomaticSize.X, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 10),
    BackgroundTransparency = 0.12, BorderSizePixel = 0, ZIndex = 20 }, gui)
bindTheme(wm, "BackgroundColor3", "panel")
corner(wm, 9); pad(wm, 30, 0, 12, 0)
local wmStroke = stroke(wm, T.line, 1, 0.2)
bindTheme(wmStroke, "Color", "line")
local wmLogo = new("ImageLabel", { Size = UDim2.fromOffset(16, 16), Position = UDim2.new(0, -21, 0.5, -8), BackgroundTransparency = 1, Image = "", ImageColor3 = WHITE, ZIndex = 21 }, wm)
Assets.watchLogo(wmLogo)
local wmLogoGrad = bindGrad(new("UIGradient", {}, wmLogo), "flow")
local wmText = label(wm, BRAND_TITLE, 12, "text", F.bold, XL)
wmText.Size = UDim2.fromOffset(0, 28); wmText.AutomaticSize = Enum.AutomaticSize.X; wmText.ZIndex = 21
local wmLine = new("Frame", { Size = UDim2.new(1, 42, 0, 2), Position = UDim2.new(0, -30, 1, -2), BorderSizePixel = 0, BackgroundColor3 = WHITE, ZIndex = 22 }, wm)
local wmGrad = bindGrad(new("UIGradient", {}, wmLine), "flow")

local fab = { cx = 40, cy = 200, idleT = 0, a = 1, aT = 1, size = 46, ringT = 0, press = nil }
local fabRoot = new("Frame", { Name = "fab", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(46, 46), Position = UDim2.fromOffset(40, 200), BackgroundTransparency = 1,
    BorderSizePixel = 0, ZIndex = 60 }, gui)
local fabScale = new("UIScale", { Scale = 1 }, fabRoot)
local fabGlow = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(2.6, 2.6), BackgroundTransparency = 1, Image = "",
    ImageTransparency = 0.7, ZIndex = 60, BorderSizePixel = 0 }, fabRoot)
bindTheme(fabGlow, "ImageColor3", "acc")
Assets.watchTex(fabGlow, "glow")
local fabRing = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 60 }, fabRoot)
corner(fabRing, UDim.new(1, 0))
local ringStroke = stroke(fabRing, WHITE, 2, 1)
bindGrad(new("UIGradient", {}, ringStroke), "flow")
local fabBody = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 0.08, Text = "", AutoButtonColor = false, BorderSizePixel = 0, ZIndex = 61 }, fabRoot)
bindTheme(fabBody, "BackgroundColor3", "panel")
corner(fabBody, UDim.new(1, 0))
local fabStroke = stroke(fabBody, WHITE, 2.5, 0)
local fabStrokeGrad = bindGrad(new("UIGradient", {}, fabStroke), "flow")
local fabLogo = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromScale(0.62, 0.62), BackgroundTransparency = 1, Image = "",
    ImageColor3 = WHITE, ZIndex = 62, BorderSizePixel = 0 }, fabBody)
Assets.watchLogo(fabLogo)
bindGrad(new("UIGradient", {}, fabLogo), "flow")
local fabClose = UIX.icon(fabBody, "ic_close", 18, "text")
fabClose.AnchorPoint = Vector2.new(0.5, 0.5); fabClose.Position = UDim2.fromScale(0.5, 0.5); fabClose.Size = UDim2.fromScale(0.4, 0.4); fabClose.ImageTransparency = 1; fabClose.ZIndex = 63

local function fabHidden()
    if C("fabShow") == true then return false end
    local okK, kb = pcall(function() return UIS.KeyboardEnabled end)
    return okK and kb == true
end

local function fabPlace(animate)
    local vp = viewport()
    local S = clamp(tonumber(C("fabSize")) or 46, 34, 84)
    fab.size = S
    fabRoot.Size = UDim2.fromOffset(S, S)
    local fx = clamp(tonumber(C("fabX")) or 0.035, 0, 1) * vp.X
    local fy = clamp(tonumber(C("fabY")) or 0.42, 0, 1) * vp.Y
    fx = clamp(fx, S / 2 + 6, math.max(S / 2 + 6, vp.X - S / 2 - 6))
    fy = clamp(fy, S / 2 + 6, math.max(S / 2 + 6, vp.Y - S / 2 - 6))
    fab.cx, fab.cy = fx, fy
    if animate then tw(fabRoot, TI.pop, { Position = UDim2.fromOffset(fx, fy) }) else fabRoot.Position = UDim2.fromOffset(fx, fy) end
end

local function fabOpenVisual(open)
    tw(fabLogo, TI.med, { ImageTransparency = open and 1 or 0, Rotation = open and 90 or 0, Size = open and UDim2.fromScale(0.4, 0.4) or UDim2.fromScale(0.62, 0.62) })
    fabClose.Rotation = open and -90 or 0
    tw(fabClose, TI.back, { ImageTransparency = open and 0 or 1, Rotation = open and 0 or 90 })
    fab.idleT = 0
end

local function fabApplyAlpha()
    local a = fab.a
    fabBody.BackgroundTransparency = 1 - a * 0.92
    fabStroke.Transparency = 1 - a
    fabGlow.ImageTransparency = 1 - a * 0.3
    if not menuOpen then fabLogo.ImageTransparency = 1 - a end
end

bind(UIS.InputChanged, function(i)
    local p = fab.press
    if p and isMove(i) then
        local d = i.Position - p.start
        if p.moved or d.Magnitude > 9 then
            p.exceeded = true
            if C("fabLock") ~= true then
                p.moved = true
                local vp = viewport()
                local S = fab.size
                fab.cx = clamp(p.cx + d.X, S / 2 + 4, vp.X - S / 2 - 4)
                fab.cy = clamp(p.cy + d.Y, S / 2 + 4, vp.Y - S / 2 - 4)
                fabRoot.Position = UDim2.fromOffset(fab.cx, fab.cy)
            end
        end
    end
end)
fabBody.InputBegan:Connect(function(i)
    if isPress(i) and not fab.press then
        fab.press = { start = i.Position, cx = fab.cx, cy = fab.cy, moved = false, exceeded = false }
        fab.idleT = 0
        tw(fabScale, TI.fast, { Scale = 0.86 })
    end
end)
bind(UIS.InputEnded, function(i)
    local p = fab.press
    if p and isPress(i) then
        fab.press = nil
        tw(fabScale, TI.back, { Scale = 1 })
        fab.idleT = 0
        if p.moved then
            local vp = viewport()
            local S = fab.size
            local tx = fab.cx
            if C("fabSnap") ~= false then tx = (fab.cx < vp.X / 2) and (S / 2 + 8) or (vp.X - S / 2 - 8) end
            fab.cx = tx
            cfg.fabX = tx / vp.X
            cfg.fabY = fab.cy / vp.Y
            tw(fabRoot, TI.pop, { Position = UDim2.fromOffset(fab.cx, fab.cy) })
        elseif not p.exceeded then
            UI.toggle()
        end
    end
end)

local function fabStep(d, t)
    if fabRoot.Visible then
        local open = menuOpen
        fab.idleT = fab.idleT + d
        local idle = (not open) and fab.idleT > 3.5 and (tonumber(C("fabIdle")) or 0.5) < 1 and not fab.press
        fab.aT = idle and clamp(tonumber(C("fabIdle")) or 0.5, 0.15, 1) or 1
        local k = damp(5, d)
        if math.abs(fab.aT - fab.a) > 0.004 then
            fab.a = fab.a + (fab.aT - fab.a) * k
            fabApplyAlpha()
        end
        if UIX.perfTier < 3 and not C("uiLite") then
            fabStrokeGrad.Rotation = (t * 70) % 360
            if not open then fabLogo.Rotation = (t * 26) % 360 end
            local br = 2.6 + math.sin(t * 2.2) * 0.15
            fabGlow.Size = UDim2.fromScale(br, br)
            if C("fabPulse") ~= false and not open and fab.a > 0.8 then
                fab.ringT = fab.ringT + d
                local cyc = 3.8
                local u = (fab.ringT % cyc) / 1.9
                if u <= 1 then
                    local s = 1 + u * 0.7
                    fabRing.Size = UDim2.fromScale(s, s)
                    ringStroke.Transparency = 0.3 + u * 0.7
                else
                    ringStroke.Transparency = 1
                end
            else
                ringStroke.Transparency = 1
            end
        end
    end
end

local function mkDeco(name, tex, tint, z)
    local o = new("ImageLabel", { Name = name, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(0, 0),
        BackgroundTransparency = 1, Image = "", ImageTransparency = 1, ImageColor3 = WHITE, ZIndex = z, Visible = false, BorderSizePixel = 0, Active = false }, shell)
    if tint then bindTheme(o, "ImageColor3", tint) end
    Assets.watchTex(o, tex)
    return o
end
local maCore = mkDeco("maCore", "glow", "acc2", 0)
local maRing = mkDeco("maRing", "ring", "acc", 0)
local maFlare = mkDeco("maFlare", "twinkle", nil, 12)

local function eOutBack(u, c) local v = u - 1; return 1 + (c + 1) * v * v * v + c * v * v end
local function eInBack(u, c) return (c + 1) * u * u * u - c * u * u end
local function eOutCubic(u) local v = 1 - u; return 1 - v * v * v end
local function eInCubic(u) return u * u * u end
local function eOutQuint(u) local v = 1 - u; return 1 - v * v * v * v * v end
local function eInQuad(u) return u * u end
local function eOutQuad(u) return 1 - (1 - u) * (1 - u) end
local function seg(u, a, b) return clamp((u - a) / math.max(b - a, 1e-4), 0, 1) end
local function mix(a, b, k) return a + (b - a) * k end

local MA = { dir = 0, t = 0, dur = 0.7, tail = 0, fade = false, cs = 0.02, tok = 0,
    cur = { sc = 1, gt = 1, bt = 1, st = 1 }, from = { sc = 1, gt = 1, bt = 1, st = 1 } }
UIX.MA = MA
UI._ma = MA

local function maApply(sc, gt, bt, st)
    local c = MA.cur
    sc = clamp(sc, 0.01, 1.25)
    c.sc, c.gt, c.bt, c.st = sc, gt, bt, st
    UIX.popScale.Scale = sc
    UIX.borderPop.Scale = sc
    UIX.shadowPop.Scale = sc
    if UIX.isCanvas then win.GroupTransparency = gt end
    UIX.borderStroke.Transparency = bt
    UIX.shadow.ImageTransparency = st
end
local function maDeco(core, ring, flare)
    for i, o in ipairs({ maCore, maRing, maFlare }) do
        local d = (i == 1 and core) or (i == 2 and ring) or flare
        if d then
            o.Visible = true
            o.Size = UDim2.fromOffset(d[1], d[1])
            o.ImageTransparency = d[2]
            if d[3] then o.Rotation = d[3] end
        elseif o.Visible then
            o.Visible = false
        end
    end
end
local OPEN_T = function() return { sc = 1, gt = 0, bt = 0.1, st = UIX.shadowRest } end

local function maFinish(opened)
    MA.dir = 0
    maDeco(nil, nil, nil)
    if opened then
        local o = OPEN_T()
        maApply(o.sc, o.gt, o.bt, o.st)
        shell.Position = UIX.basePos()
    else
        maApply(MA.cs, 1, 1, 1)
        shell.Visible = false
    end
    UIX.animating = false
end

local function maStep(dt)
    if MA.dir == 0 then return end
    MA.t = MA.t + dt
    local t, F = MA.t, MA.from
    local R = math.max(shell.Size.X.Offset, shell.Size.Y.Offset)
    if MA.dir > 0 then
        local u = clamp(t / MA.dur, 0, 1)
        local sc
        if MA.fade then sc = mix(F.sc, 1, eOutQuint(u)) else sc = mix(F.sc, 1, eOutBack(u, 1.05)) end
        local o = OPEN_T()
        maApply(sc,
            mix(F.gt, o.gt, eOutQuad(seg(u, 0, MA.fade and 1 or 0.5))),
            mix(F.bt, o.bt, eOutQuad(seg(u, 0.2, 0.8))),
            mix(F.st, o.st, eOutQuad(seg(u, 0.1, 1))))
        if not MA.fade then
            local tu = t / (MA.dur + MA.tail)
            local core, ring, flare
            local a = seg(tu, 0, 0.16)
            local ct = mix(1, 0.12, a)
            if tu > 0.16 then ct = mix(0.12, 1, eInQuad(seg(tu, 0.16, 0.92))) end
            if tu < 0.98 then core = { 70 + R * 0.55 * eOutCubic(seg(tu, 0, 0.85)), ct } end
            if tu < 0.95 then ring = { 30 + R * 1.25 * eOutCubic(seg(tu, 0, 0.9)), mix(0.2, 1, eOutQuad(seg(tu, 0.05, 0.9))) } end
            if tu < 0.5 then flare = { 40 + 260 * eOutCubic(seg(tu, 0, 0.5)), mix(0.05, 1, eInQuad(seg(tu, 0.08, 0.5))), 45 * tu } end
            maDeco(core, ring, flare)
        end
        if t >= MA.dur + MA.tail then maFinish(true) end
    else
        local u = clamp(t / MA.dur, 0, 1)
        local sc
        if MA.fade then sc = mix(F.sc, MA.cs, eOutQuad(u)) else sc = mix(F.sc, MA.cs, eInBack(u, 1.25)) end
        maApply(sc,
            mix(F.gt, 1, eInQuad(seg(u, MA.fade and 0 or 0.3, 1))),
            mix(F.bt, 1, eOutQuad(seg(u, 0.05, 0.75))),
            mix(F.st, 1, eOutQuad(seg(u, 0, 0.9))))
        if not MA.fade then
            local tu = t / (MA.dur + MA.tail)
            local uw = clamp(t / MA.dur, 0, 1)
            local core, ring, flare
            if uw < 1 then ring = { 24 + R * 1.15 * (1 - eInCubic(seg(uw, 0, 0.92))), mix(1, 0.35, eOutQuad(seg(uw, 0, 0.25))) + (uw > 0.25 and (0.65 * seg(uw, 0.25, 1)) or 0) } end
            local cs = seg(uw, 0.4, 1)
            if t < MA.dur then
                core = { 60 + R * 0.3 * eOutCubic(cs), mix(1, 0.2, eOutQuad(cs)) }
            else
                local k = seg(t, MA.dur, MA.dur + MA.tail)
                core = { (60 + R * 0.3) * (1 - eInCubic(k)) + 8, mix(0.2, 1, eOutQuad(k)) }
                flare = { 30 + 240 * eOutCubic(k), mix(0.05, 1, eInQuad(k)), 70 * k }
            end
            maDeco(core, ring, flare)
        end
        if t >= MA.dur + MA.tail then maFinish(false) end
    end
end
UIX.maStep = maStep

local toggleToken = 0
function UI.toggle(v)
    if v == nil then v = not menuOpen end
    local was = menuOpen
    menuOpen = v
    toggleToken = toggleToken + 1
    local my = toggleToken
    UIX.closeDD()
    if not v and UIX.closeSearch then UIX.closeSearch() end
    fabOpenVisual(v)
    if v == was and shell.Visible == v then return end
    local mode = tostring(C("menuAnim") or "Pull to center")
    local D = clamp(tonumber(C("menuAnimT")) or 0.7, 0.25, 1.5)
    UIX.animating = true
    MA.tok = my
    local from = MA.from
    if v then
        UIX.layout(true)
        local wasShown = shell.Visible
        shell.Visible = true
        shell.Position = UIX.basePos()
        for ctl in pairs(sliderAnim) do sliderAnim[ctl] = nil; ctl.vis = ctl.tgt; if ctl.paint then ctl.paint() end end
        if mode == "Off" then
            MA.dir = 0
            maFinish(true)
            local ct = UIX.getTab(); if ct then UIX.revealPage(ct) end
            return
        end
        MA.fade = (mode == "Fade")
        MA.cs = MA.fade and 0.94 or 0.02
        if wasShown then
            from.sc, from.gt, from.bt, from.st = MA.cur.sc, MA.cur.gt, MA.cur.bt, MA.cur.st
        else
            from.sc, from.gt, from.bt, from.st = MA.cs, 1, 1, 1
            maApply(from.sc, from.gt, from.bt, from.st)
        end
        MA.dir, MA.t, MA.dur, MA.tail = 1, 0, D, MA.fade and 0 or 0.18
        local ct = UIX.getTab()
        task.delay(MA.fade and 0.12 or D * 0.3, function()
            if toggleToken == my and ct then UIX.revealPage(ct) end
        end)
    else
        if mode == "Off" then
            MA.dir = 0
            maFinish(false)
            return
        end
        MA.fade = (mode == "Fade")
        MA.cs = MA.fade and 0.94 or 0.02
        from.sc, from.gt, from.bt, from.st = MA.cur.sc, MA.cur.gt, MA.cur.bt, MA.cur.st
        if not shell.Visible then from.sc, from.gt, from.bt, from.st = 1, 0, 0.1, UIX.shadowRest end
        MA.dir, MA.t, MA.dur, MA.tail = -1, 0, D * 0.8, MA.fade and 0 or 0.2
    end
    task.delay(MA.dur + MA.tail + 0.3, function()
        if toggleToken == my and MA.dir ~= 0 then maFinish(v) end
    end)
end
UI.isOpen = function() return menuOpen end

local splash
function UI.splash()
    if splash then return splash end
    local s = {}
    local f = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = T.bg, BackgroundTransparency = 1, ZIndex = 100, Active = true, BorderSizePixel = 0 }, gui)
    local cx = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(300, 260), BackgroundTransparency = 1, ZIndex = 101, BorderSizePixel = 0 }, f)
    new("UIScale", { Scale = clamp(curScale() + 0.1, 0.7, 1.3) }, cx)
    local glow = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(150, 80), Size = UDim2.fromOffset(240, 240), BackgroundTransparency = 1, Image = "",
        ImageColor3 = T.acc2, ImageTransparency = 1, ZIndex = 101, BorderSizePixel = 0 }, cx)
    local logo = new("ImageLabel", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(150, 80), Size = UDim2.fromOffset(150, 150), BackgroundTransparency = 1, Image = "",
        ImageColor3 = WHITE, ImageTransparency = 1, ZIndex = 102, BorderSizePixel = 0 }, cx)
    Assets.watchLogo(glow); Assets.watchLogo(logo)
    local lg = new("UIGradient", { Color = UIX.seqFor("flow") }, logo)
    local ttl = new("TextLabel", { BackgroundTransparency = 1, Text = BRAND_TITLE, TextSize = 28, Font = F.black, TextColor3 = T.text, TextTransparency = 1, AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.fromOffset(150, 170), Size = UDim2.fromOffset(300, 34), ZIndex = 102, BorderSizePixel = 0 }, cx)
    local sub = new("TextLabel", { BackgroundTransparency = 1, Text = BRAND_SUB, TextSize = 12, Font = F.med, TextColor3 = T.dim, TextTransparency = 1, AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.fromOffset(150, 204), Size = UDim2.fromOffset(300, 16), ZIndex = 102, BorderSizePixel = 0 }, cx)
    local trackF = new("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromOffset(150, 232), Size = UDim2.fromOffset(180, 4), BackgroundColor3 = T.off, BackgroundTransparency = 1,
        BorderSizePixel = 0, ZIndex = 102 }, cx)
    corner(trackF, 2)
    local fillF = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = WHITE, BorderSizePixel = 0, ZIndex = 103 }, trackF)
    corner(fillF, 2)
    new("UIGradient", { Color = UIX.seqFor("lin") }, fillF)
    tw(f, TI.slow, { BackgroundTransparency = 0.08 })
    tw(glow, TI.slow, { ImageTransparency = 0.72 })
    tw(logo, TI.slow, { ImageTransparency = 0 })
    tw(ttl, TI.slow, { TextTransparency = 0 })
    tw(sub, TI.slow, { TextTransparency = 0 })
    tw(trackF, TI.slow, { BackgroundTransparency = 0 })
    local shown = 0
    function s.step(dt)
        local t = os.clock()
        logo.Rotation = (t * 24) % 360
        glow.Rotation = (-t * 14) % 360
        lg.Rotation = (t * 90) % 360
        local g = 240 + math.sin(t * 2) * 12
        glow.Size = UDim2.fromOffset(g, g)
        local p = Assets.total > 0 and (Assets.ready / Assets.total) or 1
        if Assets.done then p = 1 end
        shown = shown + (p - shown) * damp(6, dt)
        fillF.Size = UDim2.fromScale(clamp(shown, 0, 1), 1)
        sub.Text = Assets.done and "ready" or ("loading textures  " .. Assets.ready .. " / " .. Assets.total)
    end
    function s.finish()
        s.done = true
        tw(f, TI.slow, { BackgroundTransparency = 1 })
        tw(glow, TI.slow, { ImageTransparency = 1 })
        tw(logo, TI.slow, { ImageTransparency = 1, Size = UDim2.fromOffset(220, 220) })
        tw(ttl, TI.slow, { TextTransparency = 1 })
        tw(sub, TI.slow, { TextTransparency = 1 })
        tw(trackF, TI.slow, { BackgroundTransparency = 1 })
        tw(fillF, TI.slow, { BackgroundTransparency = 1 })
        task.delay(0.5, function() pcall(function() f:Destroy() end); splash = nil end)
    end
    splash = s
    return s
end

local inkTok = 0
function UIX.inkSpread(pal, onCovered)
    inkTok = inkTok + 1
    local my = inkTok
    local ink = UIX.ink
    local sc = curScale()
    local W_, H_ = shell.Size.X.Offset, shell.Size.Y.Offset
    local ox, oy = W_ / 2, H_ / 2
    local o = UIX.inkOrigin
    if o and os.clock() - o.t < 2.5 then
        local a = shell.AbsolutePosition
        local lx, ly = (o.x - a.X) / sc, (o.y - a.Y) / sc
        if lx == lx and ly == ly then ox, oy = clamp(lx, 0, W_), clamp(ly, 0, H_) end
    end
    UIX.inkOrigin = nil
    for _, c in ipairs(ink:GetChildren()) do pcall(function() c:Destroy() end) end
    ink.Visible = true
    local R = math.sqrt(math.max(ox, W_ - ox) ^ 2 + math.max(oy, H_ - oy) ^ 2) * 1.05
    local dur = 0.7 / math.max(UIX.speed or 1, 0.4)
    local ti = TweenInfo.new(dur, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local function disc(col, tr, delay, scaleR)
        local f = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(ox, oy), Size = UDim2.fromOffset(0, 0), BackgroundColor3 = col,
            BackgroundTransparency = tr, BorderSizePixel = 0, ZIndex = 1 }, ink)
        corner(f, UDim.new(1, 0))
        task.delay(delay, function()
            if inkTok == my and f.Parent then
                tw(f, ti, { Size = UDim2.fromOffset(R * 2 * scaleR, R * 2 * scaleR) })
            end
        end)
        return f
    end
    local d1 = disc(pal.acc, 0.18, 0, 1)
    local d2 = disc(pal.acc2, 0.3, 0.05, 0.96)
    local d3 = disc(pal.bg, 0.02, 0.1, 0.92)
    new("UIGradient", { Rotation = 35, Color = ColorSequence.new({ CK(0, pal.bg), CK(1, pal.panel2) }) }, d3)
    local rim = new("Frame", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(ox, oy), Size = UDim2.fromOffset(0, 0), BackgroundTransparency = 1,
        BorderSizePixel = 0, ZIndex = 2 }, ink)
    corner(rim, UDim.new(1, 0))
    local rs = stroke(rim, pal.acc3, 3, 0.1)
    tw(rim, ti, { Size = UDim2.fromOffset(R * 2, R * 2) })
    tw(rs, ti, { Transparency = 0.9 })
    task.delay(dur + 0.16, function()
        if inkTok ~= my or UIX.dead then return end
        local ok, e = pcall(onCovered)
        if not ok then report("ink-swap", e) end
        local fade = TweenInfo.new(0.5 / math.max(UIX.speed or 1, 0.4), Enum.EasingStyle.Sine, Enum.EasingDirection.In)
        for _, f in ipairs({ d1, d2, d3 }) do tw(f, fade, { BackgroundTransparency = 1 }) end
        task.delay(0.55 / math.max(UIX.speed or 1, 0.4), function()
            if inkTok == my then
                ink.Visible = false
                for _, c in ipairs(ink:GetChildren()) do pcall(function() c:Destroy() end) end
            end
        end)
    end)
end

local sigs = {}
local function sigOf(...)
    local t = { ... }
    for i = 1, #t do t[i] = tostring(t[i]) end
    return table.concat(t, "|")
end

function UIX.applyAppearance(force)
    local spd = tonumber(C("uiAnim")) or 1
    if force or sigs.spd ~= spd then sigs.spd = spd; UIX.rebuildTI(spd) end

    local tkey = sigOf(C("theme"), C("accentOn"))
    local hkey = C("accentOn") and tostring(C("accentH")) or ""
    local bgKeys = sigOf(C("bgScene"), C("bgId"), C("bgIdMode"), C("bgDim"), C("bgSheet"), C("bgFW"), C("bgFH"))
    local function swap()
        UIX.resolveTheme()
        UIX.pushTheme()
        UIX.applyBackground(true)
        UIX.applyParticles()
    end
    if force or sigs.tkey == nil then
        sigs.tkey, sigs.hkey, sigs.bg = tkey, hkey, bgKeys
        swap()
    elseif tkey ~= sigs.tkey then
        sigs.tkey, sigs.hkey, sigs.bg = tkey, hkey, bgKeys
        if menuOpen and shell.Visible and not C("uiLite") then
            UIX.inkSpread(UIX.computePalette({}), swap)
        elseif menuOpen and shell.Visible then
            tw(UIX.flash, TI.fast, { BackgroundTransparency = 0.05 })
            task.delay(0.13, function()
                swap()
                tw(UIX.flash, TI.slow, { BackgroundTransparency = 1 })
            end)
        else
            swap()
        end
    elseif hkey ~= sigs.hkey then
        sigs.hkey = hkey
        UIX.resolveTheme()
        UIX.pushTheme()
    end
    if bgKeys ~= sigs.bg then
        sigs.bg = bgKeys
        UIX.applyBackground(false)
    else
        UIX.applyBackground(false)
    end
    local psig = sigOf(C("bgPart"), C("bgPartN"), C("uiLite"))
    if force or psig ~= sigs.part then sigs.part = psig; UIX.applyParticles() end
    local gs = tostring(C("glass"))
    if force or gs ~= sigs.glass then sigs.glass = gs; UIX.applyGlass() end
    local vp = viewport()
    local lsig = sigOf(C("uiScale"), vp.X, vp.Y, C("sbCollapsed"))
    if force or lsig ~= sigs.layout then
        sigs.layout = lsig
        UIX.layout(force == true or not menuOpen)
        notifScale.Scale = clamp(curScale(), 0.7, 1.25)
        fabPlace(false)
    end
    local fsig = sigOf(C("fabShow"), C("fabSize"))
    if force or fsig ~= sigs.fab then
        sigs.fab = fsig
        fabRoot.Visible = not fabHidden()
        fabPlace(false)
    end
    wm.Visible = C("watermark") == true
    UIX.paintAllTabs(true)
end

local uiAcc, gradT = 0, 0
function UI.step(dt)
    if MA.dir ~= 0 then maStep(dt) end
    if dirty.ui then
        dirty.ui = false
        local ok, e = pcall(UIX.applyAppearance, false)
        if not ok then report("ui-apply", e) end
    end
    if splash and not splash.done then splash.step(dt) end
    if next(sliderAnim) ~= nil then
        local k = damp(18, dt)
        for ctl in pairs(sliderAnim) do
            ctl.vis = ctl.vis + (ctl.tgt - ctl.vis) * k
            if math.abs(ctl.tgt - ctl.vis) < 0.002 then ctl.vis = ctl.tgt; sliderAnim[ctl] = nil end
            ctl.paint()
        end
    end
    uiAcc = uiAcc + dt
    if uiAcc < 0.033 then return end
    local d = uiAcc
    uiAcc = 0
    local t = os.clock()
    local th = UIX.T.theme
    gradT = gradT + d * ((th and th.fast) and 0.95 or 0.38)
    fabStep(d, t)
    local lite = C("uiLite") == true or UIX.perfTier >= 3
    if wm.Visible and not lite then
        wmGrad.Offset = Vector2.new(math.sin(gradT) * 0.6, 0)
    end
    if shell.Visible then
        if not lite then
            UIX.topGrad.Offset = Vector2.new(math.sin(gradT) * 0.6, 0)
            UIX.borderGrad.Rotation = (gradT * 55) % 360
            UIX.logoGrad.Rotation = (gradT * 70) % 360
            UIX.blobStep(t)
        end
        UIX.bgStep(t, d)
        if not lite or C("bgSheet") == true then UIX.partStep(t, d) end
    end
end

