local CFG_DIR = "AfraidUI/configs"
local AUTO_FILE = "AfraidUI/autoload.txt"
local hasFs = type(writefile) == "function" and type(readfile) == "function" and type(isfolder) == "function" and type(makefolder) == "function"
local cfgPickCtl
local SKIP_SAVE = { cfgName = true, cfgPick = true }

local function ensureDirs()
    if not hasFs then return false end
    pcall(function() if not isfolder("AfraidUI") then makefolder("AfraidUI") end end)
    pcall(function() if not isfolder(CFG_DIR) then makefolder(CFG_DIR) end end)
    return true
end

local function cleanName(n)
    n = tostring(n or ""):gsub("[^%w_%-]", "_")
    if n == "" then n = "my_config" end
    return n
end

local function cfgList()
    local out = {}
    if not hasFs or type(listfiles) ~= "function" then return out end
    pcall(function()
        for _, p in ipairs(listfiles(CFG_DIR)) do
            local n = tostring(p):match("([^/\\]+)%.json$")
            if n then out[#out + 1] = n end
        end
    end)
    table.sort(out)
    return out
end

local function refreshCfgList()
    if cfgPickCtl then
        local l = cfgList()
        cfgPickCtl:SetOptions(#l > 0 and l or { "(none)" })
    end
end

local function cfgSave(name)
    if not ensureDirs() then notify("No file API in this executor", 3) return end
    name = cleanName(name)
    local data = {}
    for k, v in pairs(cfg) do
        if not SKIP_SAVE[k] then
            local tv = type(v)
            if tv == "number" or tv == "boolean" or tv == "string" then data[k] = v
            elseif tv == "table" then data[k] = copyT(v) end
        end
    end
    data._v = VERSION
    local ok, json = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok then report("config", json) return end
    local ok2, err = pcall(writefile, CFG_DIR .. "/" .. name .. ".json", json)
    if ok2 then notify("Saved config: " .. name, 2.5); refreshCfgList() else report("config", err) end
end

local applyLoaded
local function cfgLoad(name, quiet)
    if not hasFs then return false end
    name = cleanName(name)
    local path = CFG_DIR .. "/" .. name .. ".json"
    local ok, raw = pcall(function() if isfile(path) then return readfile(path) end end)
    if not ok or not raw then
        if not quiet then notify("Config not found: " .. name, 3) end
        return false
    end
    local ok2, data = pcall(function() return HttpService:JSONDecode(raw) end)
    if not ok2 or type(data) ~= "table" then
        if not quiet then notify("Config is corrupt: " .. name, 3) end
        return false
    end
    for k, v in pairs(data) do
        if k ~= "_v" and not SKIP_SAVE[k] and cfg[k] ~= nil and type(cfg[k]) == type(v) then
            local f = Flags[k]
            if f and f.Set then f:Set(v, true) else cfg[k] = v end
        end
    end
    applyLoaded()
    if not quiet then notify("Loaded config: " .. name, 2.5) end
    return true
end

applyLoaded = function()
    if type(cfg.binds) ~= "table" then cfg.binds = {} end
    UIX.refreshBinds()
    mark("ui")
    UI.applyAppearance(true)
end

local function autoloadName()
    if not hasFs then return nil end
    local ok, n = pcall(function() if isfile(AUTO_FILE) then return readfile(AUTO_FILE) end end)
    if ok and n and n ~= "" then return cleanName((tostring(n):gsub("%s", ""))) end
end

