local API
local unloaded = false
local statAcc, fpsN, fpsT = 0, 0, 0
local userSteps, userUnloads = {}, {}

local function step(dt)
    if unloaded then return end
    try("ui", UI.step, dt)
    for i = 1, #userSteps do try("user", userSteps[i], dt) end
    fpsN = fpsN + 1
    fpsT = fpsT + dt
    statAcc = statAcc + dt
    if statAcc >= 1 then
        local fps = fpsN / math.max(fpsT, 0.001)
        fpsN, fpsT, statAcc = 0, 0, 0
        local f = math.floor(fps + 0.5)
        UI.setWatermark(("%s  |  %d fps"):format(BRAND_TITLE, f))
        UI.setStatus(("%d fps"):format(f))
        UI.setFps(("%d fps"):format(f))
        UI.setPerf(fps < 18 and 3 or (fps < 26 and 2 or 0))
    end
end

bind(RunService.RenderStepped, step)

bind(UIS.InputBegan, function(i, gp)
    if unloaded then return end
    local lis = UI.getListening()
    if lis then
        if i.UserInputType == Enum.UserInputType.Keyboard then
            if i.KeyCode == Enum.KeyCode.Escape then lis(nil) else lis(i.KeyCode.Name) end
            UI.clearListening()
        end
        return
    end
    if gp then return end
    if i.UserInputType == Enum.UserInputType.Keyboard then
        local kn = i.KeyCode.Name
        if kn == cfg.menuKey then UI.toggle() end
        UIX.fireBind(kn, true)
    end
end)
bind(UIS.InputEnded, function(i)
    if i.UserInputType == Enum.UserInputType.Keyboard then
        UIX.fireBind(i.KeyCode.Name, false)
    end
end)

unload = function()
    if unloaded then return end
    unloaded = true
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    for _, f in ipairs(userUnloads) do pcall(f) end
    pcall(UI.destroy)
    if genv.AS_UNLOAD == unload then genv.AS_UNLOAD = nil end
    if genv.AFRAID_SIDE == API then genv.AFRAID_SIDE = nil end
end
genv.AS_UNLOAD = unload

API = {
    version = VERSION, cfg = cfg, Flags = Flags, notify = notify, mark = mark,
    Tabs = { Combat = tCombat, Visuals = tVisuals, Movement = tMovement, Misc = tMisc, Config = tConfig },
    Tab = function(name) return UIX.tabByName[name] end,
    NewTab = function(name, iconName) return UITab(name, iconName or "ic_misc", nil) end,
    Section = function(tabName, side, title, grp)
        local t = UIX.tabByName[tabName]
        if not t then return nil end
        return t:Section(side or "L", title or "Section", grp)
    end,
    OnStep = function(fn) userSteps[#userSteps + 1] = fn; return fn end,
    OnUnload = function(fn) userUnloads[#userUnloads + 1] = fn; return fn end,
    Unload = function() unload() end,
}
genv.AFRAID_SIDE = API

if genv.AS_TEST == true then
    genv.AS_TEST = { cfg = cfg, Flags = Flags, UI = UI, UIX = UIX, dirty = dirty, mark = mark, LOG = LOG, unload = unload, Assets = Assets, D = D, API = API }
end

