hitLogFrame.BorderSizePixel = 0; hitLogFrame.Visible = false; hitLogFrame.Parent = hitScreen
local _hlC = Instance.new("UICorner"); _hlC.CornerRadius = UDim.new(0,5); _hlC.Parent = hitLogFrame
local _hlS = Instance.new("UIStroke"); _hlS.Color = Color3.fromRGB(40,40,45); _hlS.Thickness = 1; _hlS.Parent = hitLogFrame
local _hlTitle = Instance.new("TextLabel"); _hlTitle.Size = UDim2.new(1,0,0,18); _hlTitle.BackgroundTransparency = 1
_hlTitle.Text = "HIT LOG"; _hlTitle.TextColor3 = Color3.fromRGB(80,80,85)
_hlTitle.Font = Enum.Font.GothamBold; _hlTitle.TextSize = 9; _hlTitle.Parent = hitLogFrame
local _hlList = Instance.new("Frame"); _hlList.Size = UDim2.new(1,-4,1,-22); _hlList.Position = UDim2.new(0,2,0,20)
_hlList.BackgroundTransparency = 1; _hlList.Parent = hitLogFrame
local _hlLayout = Instance.new("UIListLayout"); _hlLayout.Padding = UDim.new(0,1); _hlLayout.Parent = _hlList

local function UpdateHitLog()
    for _, c in pairs(_hlList:GetChildren()) do
        if not c:IsA("UIListLayout") then c:Destroy() end
    end
    for i, hit in ipairs(St.hitLog) do
        if i > 10 then break end
        local lbl = Instance.new("TextLabel"); lbl.Size = UDim2.new(1,0,0,14); lbl.BackgroundTransparency = 1
        lbl.Text = hit.name.." | "..hit.damage..(hit.killed and " | KILL" or "")
        lbl.TextColor3 = hit.killed and Color3.fromRGB(255,50,50) or Color3.fromRGB(160,160,165)
        lbl.Font = Enum.Font.Gotham; lbl.TextSize = 9; lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.Parent = _hlList
    end
end

local function ShowHitmarker(player, damage, killed)
    if not Cfg.HitmarkerESP then return end
    local char = player.Character; if not char then return end
    local head = char:FindFirstChild("Head"); if not head then return end
    local sp, onScreen = Camera:WorldToViewportPoint(head.Position + Vector3.new(0,2,0))
    if not onScreen then return end
    local color = killed and Color3.fromRGB(255,50,50) or (damage > 50 and Color3.fromRGB(255,255,50) or Color3.fromRGB(50,255,50))
    local text = Drawing.new("Text"); text.Text = tostring(math.floor(damage)); text.Position = Vector2.new(sp.X,sp.Y-25)
    text.Color = color; text.Size = 18; text.Font = 3; text.Center = true; text.Outline = true
    text.OutlineColor = Color3.fromRGB(0,0,0); text.Visible = true
    local l1 = Drawing.new("Line"); l1.Thickness=2; l1.Color=color; l1.From=Vector2.new(sp.X-8,sp.Y); l1.To=Vector2.new(sp.X+8,sp.Y); l1.Visible=true
    local l2 = Drawing.new("Line"); l2.Thickness=2; l2.Color=color; l2.From=Vector2.new(sp.X,sp.Y-8); l2.To=Vector2.new(sp.X,sp.Y+8); l2.Visible=true
    task.spawn(function()
        local e = 0
        while e < 1.5 do
            e = e + 0.03
            local a = 1 - (e/1.5)
            text.Transparency=1-a; l1.Transparency=1-a; l2.Transparency=1-a
            text.Position = Vector2.new(sp.X, sp.Y-25-e*25)
            task.wait(0.03)
        end
        text:Remove(); l1:Remove(); l2:Remove()
    end)
    table.insert(St.hitLog, 1, {name=player.Name, damage=math.floor(damage), killed=killed})
    if #St.hitLog > 10 then table.remove(St.hitLog) end
    UpdateHitLog()
end

local function HookPlayerHitmarker(player)
    if player == lp then return end
    local function hookChar()
        local char = player.Character; if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid"); if not hum then return end
        local lastHp = hum.Health
        hum.HealthChanged:Connect(function(newHp)
            if not Cfg.HitmarkerESP then return end
            local delta = lastHp - newHp; lastHp = newHp
            if delta > 0 then ShowHitmarker(player, delta, newHp <= 0) end
        end)
    end
    if player.Character then hookChar() end
    player.CharacterAdded:Connect(function() task.wait(0.5); hookChar() end)
end

for _, p in pairs(Players:GetPlayers()) do HookPlayerHitmarker(p) end
Players.PlayerAdded:Connect(HookPlayerHitmarker)

-- ===================== FLING =====================
local function FlingTarget(targetPlayer, mode)
    if not targetPlayer then notify("No target", 2) return end
    local tChar = targetPlayer.Character; if not tChar then return end
    local tRoot = tChar:FindFirstChild("HumanoidRootPart"); if not tRoot then return end
    pcall(function() setsimulationradius(1/0) end)
    mode = mode or Cfg.FlingMode

    if mode == "Loop" then
        if St.FlingLoopRunning then return end
        St.FlingLoopRunning = true
        task.spawn(function()
            for i = 1, 5 do
                if not tRoot.Parent then break end
                local lbv = Instance.new("BodyVelocity"); lbv.MaxForce=Vector3.new(math.huge,math.huge,math.huge)
                lbv.Velocity=Vector3.new(math.random(-500,500),10000,math.random(-500,500)); lbv.Parent=tRoot
                local lbav = Instance.new("BodyAngularVelocity"); lbav.MaxTorque=Vector3.new(math.huge,math.huge,math.huge)
                lbav.AngularVelocity=Vector3.new(0,500,0); lbav.Parent=tRoot
                Debris:AddItem(lbv,0.4); Debris:AddItem(lbav,0.4); task.wait(0.3)
            end
            St.FlingLoopRunning = false
        end)
        notify("Fling Loop → "..targetPlayer.Name, 2); return
    end

    local tbv  = Instance.new("BodyVelocity");  tbv.MaxForce  = Vector3.new(math.huge,math.huge,math.huge)
    local tbav = Instance.new("BodyAngularVelocity"); tbav.MaxTorque = Vector3.new(math.huge,math.huge,math.huge)
    if mode == "ForcePush" then
        tbv.Velocity = Vector3.new(math.random(-500,500),10000,math.random(-500,500)); tbav.AngularVelocity = Vector3.new(0,200,0)
    elseif mode == "Spin" then
        tbv.Velocity = Vector3.new(0,5000,0); tbav.AngularVelocity = Vector3.new(9999,9999,9999)
    elseif mode == "Silent" then
        tbv.Velocity = Vector3.new(0,3000,0); tbav.AngularVelocity = Vector3.new(0,100,0)
    end
    tbv.Parent = tRoot; tbav.Parent = tRoot
    Debris:AddItem(tbv,1); Debris:AddItem(tbav,1)

    local myRoot = GetRoot(); local myHum = GetHum()
    if myRoot and myHum and myHum.Health > 0 then
        local savedCF = myRoot.CFrame
        local mybav = Instance.new("BodyAngularVelocity"); mybav.MaxTorque=Vector3.new(math.huge,math.huge,math.huge)
        mybav.AngularVelocity=Vector3.new(0,99999,0); mybav.Parent=myRoot
        local mybv = Instance.new("BodyVelocity"); mybv.MaxForce=Vector3.new(math.huge,math.huge,math.huge)
        mybv.Velocity=Vector3.new(0,0,0); mybv.Parent=myRoot
        myRoot.CFrame = tRoot.CFrame * CFrame.new(0,3,0); task.wait(0.05)
        mybv.Velocity = (tRoot.Position - myRoot.Position).Unit * 5000
        task.delay(0.3, function()
            pcall(function() if mybav then mybav:Destroy() end; if mybv then mybv:Destroy() end end)
            task.wait()
            pcall(function() if myRoot and myRoot.Parent then myRoot.CFrame = savedCF end end)
        end)
        Debris:AddItem(mybav,0.5); Debris:AddItem(mybv,0.5)
    end
    notify("Fling "..mode.." → "..targetPlayer.Name, 2)
end

-- ===================== KILL ALL =====================
local function KillAll()
    pcall(function() setsimulationradius(1/0) end)
    local count = 0
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= lp and player.Character then
            local role = GetRole(player)
            local shouldKill = Cfg.KillAllRole == "All" or Cfg.KillAllRole == role
            if shouldKill then
                local char = player.Character
                local hum  = char:FindFirstChildOfClass("Humanoid")
                local root = char:FindFirstChild("HumanoidRootPart")
                if Cfg.KillAllMode == "HealthDrain" and hum then
                    pcall(function() hum.Health = 0 end)
                elseif Cfg.KillAllMode == "FlingKill" and root then
                    local bv = Instance.new("BodyVelocity"); bv.MaxForce=Vector3.new(math.huge,math.huge,math.huge)
                    bv.Velocity=Vector3.new(0,-9999,0); bv.Parent=root; Debris:AddItem(bv,1)
                end
                count = count + 1
            end
        end
        task.wait(0.05)
    end
    notify("Kill All → "..count.." targets", 2)
end

-- ===================== MASS TP =====================
local function MassTP()
    local myRoot = GetRoot(); if not myRoot then notify("No root", 2) return end
    pcall(function() setsimulationradius(1/0) end)
    local mode = Cfg.MassTPMode; local count = 0
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= lp and player.Character then
            local tRoot = player.Character:FindFirstChild("HumanoidRootPart")
            if tRoot then
                pcall(function()
                    if mode == "ToMe"    then tRoot.CFrame = myRoot.CFrame * CFrame.new(math.random(-3,3),0,math.random(-3,3))
                    elseif mode == "ToVoid"  then tRoot.CFrame = CFrame.new(0,-9999,0)
                    elseif mode == "Stack"   then tRoot.CFrame = myRoot.CFrame
                    elseif mode == "Scatter" then tRoot.CFrame = CFrame.new(math.random(-500,500),50,math.random(-500,500)) end
                end)
                count = count + 1
            end
            task.wait(0.1)
        end
    end
    notify("Mass TP "..mode.." → "..count.." players", 2)
end

-- ===================== FX / COSMETICS =====================
local function ClearCos()
    local char = GetChar(); if not char then return end
    for _, child in pairs(char:GetDescendants()) do
        if child.Name:find("HubC") then child:Destroy() end
    end
    notify("Cleared", 1.5)
end

local function MakeNeonRing()
    local char = GetChar(); if not char then return end
    for i = 1, 16 do
        local p = Instance.new("Part"); p.Name="HubCNeonRing"..i; p.Size=Vector3.new(0.15,0.15,0.15)
        p.Color=Color3.fromRGB(255,255,255); p.Material=Enum.Material.Neon; p.CanCollide=false; p.Anchored=true; p.Parent=char
        task.spawn(function()
            while p.Parent do
                local r = char:FindFirstChild("HumanoidRootPart")
                if r then local a=(tick()*3+(i/16)*math.pi*2); p.CFrame=CFrame.new(r.Position+Vector3.new(math.cos(a)*3,0,math.sin(a)*3)) end
                task.wait()
            end
        end)
    end
end

local function MakeLightPillar()
    local char = GetChar(); if not char then return end
    local pillar = Instance.new("Part"); pillar.Name="HubCPillar"; pillar.Size=Vector3.new(1.5,40,1.5)
    pillar.Color=Color3.fromRGB(255,255,255); pillar.Material=Enum.Material.Neon; pillar.Transparency=0.5
    pillar.CanCollide=false; pillar.Anchored=true; pillar.Parent=char
    local e=Instance.new("ParticleEmitter"); e.Parent=pillar; e.Texture="rbxassetid://241872604"
    e.Color=ColorSequence.new(Color3.fromRGB(255,255,255)); e.Rate=20; e.Lifetime=NumberRange.new(1,2)
    e.Size=NumberSequence.new(0.5,2); e.Speed=NumberRange.new(1,3); e.SpreadAngle=Vector2.new(10,10)
    task.spawn(function()
        while pillar.Parent do
            local r=char:FindFirstChild("HumanoidRootPart")
            if r then pillar.CFrame=CFrame.new(r.Position+Vector3.new(0,20,0)) end; task.wait()
        end
    end)
end

local function MakeGroundGlow()
    local char = GetChar(); if not char then return end
    local disc=Instance.new("Part"); disc.Name="HubCGround"; disc.Shape=Enum.PartType.Cylinder; disc.Size=Vector3.new(0.1,6,6)
    disc.Color=Color3.fromRGB(255,255,255); disc.Material=Enum.Material.Neon; disc.Transparency=0.3
    disc.CanCollide=false; disc.Anchored=true; disc.Parent=char
    task.spawn(function()
        while disc.Parent do
            local r=char:FindFirstChild("HumanoidRootPart")
            if r then disc.CFrame=CFrame.new(r.Position-Vector3.new(0,2.5,0))*CFrame.Angles(0,0,math.rad(90)) end; task.wait()
        end
    end)
end

local function MakeShield()
    local char=GetChar(); if not char then return end
    local shield=Instance.new("Part"); shield.Name="HubCShield"; shield.Shape=Enum.PartType.Ball; shield.Size=Vector3.new(7,7,7)
    shield.Color=Color3.fromRGB(180,180,200); shield.Material=Enum.Material.ForceField; shield.Transparency=0.7
    shield.CanCollide=false; shield.Anchored=true; shield.Parent=char
    task.spawn(function()
        while shield.Parent do
            local r=char:FindFirstChild("HumanoidRootPart")
            if r then
                local pulse=(math.sin(tick()*3)+1)/2; shield.Transparency=0.5+pulse*0.4
                local s=6+pulse*2; shield.Size=Vector3.new(s,s,s); shield.CFrame=CFrame.new(r.Position)
            end; task.wait()
        end
    end)
end

local function MakeSparkles()
    local char=GetChar(); if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    local att=Instance.new("Attachment"); att.Name="HubCSparkAtt"; att.Parent=root
    local e=Instance.new("ParticleEmitter"); e.Name="HubCSparkEm"; e.Parent=att
    e.Texture="rbxassetid://241872604"; e.Color=ColorSequence.new(Color3.fromRGB(255,255,255))
    e.Rate=40; e.Lifetime=NumberRange.new(1,2); e.Size=NumberSequence.new(0.4,0.1)
    e.Speed=NumberRange.new(2,5); e.SpreadAngle=Vector2.new(180,180); e.Acceleration=Vector3.new(0,-5,0)
end

local function MakeWings()
    local char=GetChar(); if not char then return end
    local torso=char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"); if not torso then return end
    for _, side in pairs({"L","R"}) do
        local wing=Instance.new("Part"); wing.Name="HubCWing"..side; wing.Size=Vector3.new(0.2,2.5,1.8)
        wing.Color=Color3.fromRGB(255,255,255); wing.Material=Enum.Material.ForceField
        wing.CanCollide=false; wing.Transparency=0.25
        local w=Instance.new("Weld"); w.Part0=torso; w.Part1=wing
        w.C0=CFrame.new(side=="L" and -1.5 or 1.5,0,-0.5)*CFrame.Angles(0,0,side=="L" and 0.3 or -0.3)
        w.Parent=wing; wing.Parent=char
    end
end

local function MakeTrail()
    local char=GetChar(); if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    local a0=Instance.new("Attachment"); a0.Name="HubCTrailA0"; a0.Position=Vector3.new(-1,0,0); a0.Parent=root
    local a1=Instance.new("Attachment"); a1.Name="HubCTrailA1"; a1.Position=Vector3.new(1,0,0); a1.Parent=root
    local trail=Instance.new("Trail"); trail.Name="HubCTrail"
    trail.Attachment0=a0; trail.Attachment1=a1
    trail.Color=ColorSequence.new(Color3.fromRGB(255,255,255),Color3.fromRGB(100,100,100))
    trail.Lifetime=1.5; trail.Parent=root
end

local function MakeOrbit()
    local char=GetChar(); if not char then return end
    for i=1,6 do
        local s=Instance.new("Part"); s.Name="HubCOrb"..i; s.Shape=Enum.PartType.Ball; s.Size=Vector3.new(0.3,0.3,0.3)
        s.Color=Color3.fromHSV(i/6,0,1); s.Material=Enum.Material.Neon; s.CanCollide=false; s.Anchored=true; s.Parent=char
        task.spawn(function()
            while s.Parent do
                local r=char:FindFirstChild("HumanoidRootPart")
                if r then local a=(tick()*2+(i/6)*math.pi*2); s.CFrame=CFrame.new(r.Position+Vector3.new(math.cos(a)*3,math.sin(a*0.5)*1.5,math.sin(a)*3)) end
                task.wait()
            end
        end)
    end
end

local function MakeShockwave()
    local char=GetChar(); if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    local ring=Instance.new("Part"); ring.Name="HubCShock"; ring.Shape=Enum.PartType.Cylinder
    ring.Size=Vector3.new(0.1,1,1); ring.Color=Color3.fromRGB(255,255,255); ring.Material=Enum.Material.Neon
    ring.CanCollide=false; ring.Anchored=true; ring.Parent=char
    local startPos=root.Position
    task.spawn(function()
        for i=0,1,0.02 do
            if not ring.Parent then break end
            local sz=1+i*30; ring.Size=Vector3.new(0.1,sz,sz); ring.Transparency=i
            ring.CFrame=CFrame.new(startPos-Vector3.new(0,2,0))*CFrame.Angles(0,0,math.rad(90)); task.wait()
        end
        if ring.Parent then ring:Destroy() end
    end)
end

local function MakeAfterimage()
    local char=GetChar(); if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    task.spawn(function()
        for i=1,12 do
            if not root.Parent then break end
            local clone=Instance.new("Part"); clone.Name="HubCAfter"..i; clone.Size=root.Size
            clone.Color=Color3.fromRGB(255,255,255); clone.Material=Enum.Material.Neon
            clone.Transparency=0.5+(i/24); clone.CanCollide=false; clone.Anchored=true
            clone.CFrame=root.CFrame; clone.Parent=char; Debris:AddItem(clone,1.5); task.wait(0.08)
        end
    end)
end

local function MakeCharGlow()
    local char=GetChar(); if not char then return end
    for _, part in pairs(char:GetChildren()) do
        if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
            if not part:FindFirstChild("HubCGlowMark") then
                local mark=Instance.new("BoolValue"); mark.Name="HubCGlowMark"; mark.Parent=part
                part.Material=Enum.Material.Neon; part.Color=Color3.fromRGB(255,255,255)
            end
        end
    end
end

local function MakeHat(hatType)
    local char=GetChar(); if not char then return end
    local head=char:FindFirstChild("Head"); if not head then return end
    local hat=Instance.new("Part"); hat.Name="HubCHat"; hat.CanCollide=false; hat.Material=Enum.Material.SmoothPlastic
    if hatType=="Tophat" then
        hat.Color=Color3.fromRGB(15,15,15); hat.Size=Vector3.new(1.1,1.6,1.1)
        local brim=Instance.new("Part"); brim.Name="HubCBrim"; brim.Size=Vector3.new(1.7,0.15,1.7)
        brim.Color=Color3.fromRGB(15,15,15); brim.CanCollide=false; brim.Parent=hat
        local bw=Instance.new("Weld"); bw.Part0=hat; bw.Part1=brim; bw.C0=CFrame.new(0,-0.8,0); bw.Parent=hat
    elseif hatType=="Crown" then
        hat.Color=Color3.fromRGB(255,215,0); hat.Size=Vector3.new(1.2,0.7,1.2); hat.Material=Enum.Material.Metal
    elseif hatType=="Halo" then
        hat.Color=Color3.fromRGB(255,255,200); hat.Shape=Enum.PartType.Cylinder; hat.Size=Vector3.new(0.1,1.6,1.6); hat.Material=Enum.Material.Neon
    elseif hatType=="Propeller" then
        hat.Color=Color3.fromRGB(180,180,190); hat.Size=Vector3.new(0.3,0.3,0.3)
    elseif hatType=="Bucket" then
        hat.Color=Color3.fromRGB(140,95,45); hat.Shape=Enum.PartType.Cylinder; hat.Size=Vector3.new(1,1.3,1)
    end
    local w=Instance.new("Weld"); w.Name="HubCWeld"; w.Part0=head; w.Part1=hat; w.C0=CFrame.new(0,1.3,0); w.Parent=hat; hat.Parent=char
end

local function MakeAura(auraType)
    local char=GetChar(); if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    for _, c in pairs(root:GetChildren()) do if c.Name:find("HubCAura") then c:Destroy() end end
    local e=Instance.new("ParticleEmitter"); e.Name="HubCAura"; e.Parent=root
    e.Enabled=true; e.Texture="rbxassetid://241872604"; e.Acceleration=Vector3.new(0,0,0)
    e.Lifetime=NumberRange.new(1,2); e.Speed=NumberRange.new(1,3); e.SpreadAngle=Vector2.new(45,45); e.Size=NumberSequence.new(0.5,2)
    local cfgs={
        Fire={Color=ColorSequence.new(Color3.fromRGB(255,100,0),Color3.fromRGB(255,200,0)),Rate=50,Lifetime=NumberRange.new(0.5,1),Size=NumberSequence.new(0.5,2),Speed=NumberRange.new(2,5),SpreadAngle=Vector2.new(45,45)},
        Ice={Color=ColorSequence.new(Color3.fromRGB(100,200,255),Color3.fromRGB(200,240,255)),Rate=30,Lifetime=NumberRange.new(1,2),Size=NumberSequence.new(0.3,1),Speed=NumberRange.new(1,3),SpreadAngle=Vector2.new(30,30)},
        Lightning={Color=ColorSequence.new(Color3.fromRGB(255,255,0),Color3.fromRGB(255,255,255)),Rate=40,Lifetime=NumberRange.new(0.1,0.3),Size=NumberSequence.new(0.5,3),Speed=NumberRange.new(5,10),SpreadAngle=Vector2.new(60,60)},
        Galaxy={Color=ColorSequence.new(Color3.fromRGB(75,0,130),Color3.fromRGB(255,20,147)),Rate=60,Lifetime=NumberRange.new(1,3),Size=NumberSequence.new(0.5,3),Speed=NumberRange.new(1,4),SpreadAngle=Vector2.new(180,180)},
        Gold={Color=ColorSequence.new(Color3.fromRGB(255,215,0),Color3.fromRGB(255,255,200)),Rate=35,Lifetime=NumberRange.new(0.5,1.5),Size=NumberSequence.new(0.3,1.5),Speed=NumberRange.new(1,3),SpreadAngle=Vector2.new(20,20)},
        Void={Color=ColorSequence.new(Color3.fromRGB(0,0,0),Color3.fromRGB(50,50,50)),Rate=70,Lifetime=NumberRange.new(2,4),Size=NumberSequence.new(0.5,4),Speed=NumberRange.new(1,3),SpreadAngle=Vector2.new(180,180)},
        Plasma={Color=ColorSequence.new(Color3.fromRGB(200,200,200),Color3.fromRGB(255,255,255)),Rate=80,Lifetime=NumberRange.new(0.3,0.8),Size=NumberSequence.new(1,4),Speed=NumberRange.new(3,8),SpreadAngle=Vector2.new(90,90)},
    }
    local c2=cfgs[auraType]; if c2 then for k,v in pairs(c2) do e[k]=v end end
    notify("Aura: "..auraType, 1.5)
end

