-- ---- PLAYERS tab ----
do
    local plSection = tPlayers:Section("L", "Player List", nil)
    local function RefreshPlayerList()
        -- rebuild section buttons dynamically — add via Label for now
        -- proper approach: one button per player stored in locals
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= lp then
                local role = GetRole(player)
                plSection:Button(player.Name.." ("..role..") — FLING", function()
                    FlingTarget(player, Cfg.FlingMode)
                end)
                plSection:Button(player.Name.." — TP to", function()
                    local root=GetRoot(); local tC=player.Character
                    if root and tC then
                        local tR=tC:FindFirstChild("HumanoidRootPart")
                        if tR then root.CFrame=tR.CFrame*CFrame.new(0,0,4) end
                    end
                end)
            end
        end
    end
    plSection:Button("Refresh Player List", RefreshPlayerList, true)
    RefreshPlayerList()
end

