-- ===================== RUNTIME LOOPS =====================

-- NoClip
RunService.Stepped:Connect(function()
    if Cfg.NoClip then
        local char=GetChar(); if not char then return end
        for _, part in pairs(char:GetDescendants()) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then part.CanCollide=false end
        end
    end
end)

-- Fly
RunService.RenderStepped:Connect(function()
    if Cfg.Fly and St.FlyVelocity and St.FlyGyro then
        local root=GetRoot(); if not root then return end
        St.FlyGyro.CFrame=Camera.CFrame
        local hum=GetHum(); local moveDir=hum and hum.MoveDirection or Vector3.new(0,0,0)
        local dir=(Camera.CFrame.LookVector*-moveDir.Z)+(Camera.CFrame.RightVector*moveDir.X)
        if St.FlyUp then dir=dir+Vector3.new(0,1,0) end
        if St.FlyDown then dir=dir-Vector3.new(0,1,0) end
        if UIS:IsKeyDown(Enum.KeyCode.Space) then dir=dir+Vector3.new(0,1,0) end
        if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir=dir-Vector3.new(0,1,0) end
        St.FlyVelocity.Velocity=dir*Cfg.FlySpeed
    end
end)

-- ESP
RunService.RenderStepped:Connect(function()
    if Cfg.PlayerESP then
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= lp and player.Character then
                local root2=player.Character:FindFirstChild("HumanoidRootPart")
                local head=player.Character:FindFirstChild("Head")
                if root2 and head then
                    local sp,onScreen=Camera:WorldToViewportPoint(root2.Position)
                    local spH=Camera:WorldToViewportPoint(head.Position+Vector3.new(0,1.5,0))
                    local spR=Camera:WorldToViewportPoint(root2.Position-Vector3.new(0,2,0))
                    if onScreen then
                        if not St.ESPDrawings[player] then
                            St.ESPDrawings[player]={box=Drawing.new("Square"),text=Drawing.new("Text")}
                            St.ESPDrawings[player].box.Thickness=2; St.ESPDrawings[player].box.Filled=false
                            St.ESPDrawings[player].text.Size=12; St.ESPDrawings[player].text.Font=2
                            St.ESPDrawings[player].text.Center=true; St.ESPDrawings[player].text.Outline=true
                        end
                        local d=St.ESPDrawings[player]; local role=GetRole(player)
                        local color=Cfg.RoleESP and (RoleColors[role] or Color3.fromRGB(255,255,255)) or Color3.fromRGB(255,255,255)
                        local h=math.abs(spH.Y-spR.Y); local w=h*0.5
                        d.box.Size=Vector2.new(w,h); d.box.Position=Vector2.new(sp.X-w/2,spH.Y); d.box.Color=color; d.box.Visible=true
                        local lr=GetRoot(); local dist=lr and math.floor((root2.Position-lr.Position).Magnitude) or 0
                        d.text.Text=player.Name..(Cfg.RoleESP and (" | "..role) or "").." | "..dist.."s"
                        d.text.Position=Vector2.new(sp.X,spH.Y-16); d.text.Color=color; d.text.Visible=true
                    else
                        if St.ESPDrawings[player] then St.ESPDrawings[player].box.Visible=false; St.ESPDrawings[player].text.Visible=false end
                    end
                end
            end
        end
        for p,_ in pairs(St.ESPDrawings) do
            if not p.Parent then
                if St.ESPDrawings[p].box then St.ESPDrawings[p].box:Remove() end
                if St.ESPDrawings[p].text then St.ESPDrawings[p].text:Remove() end
                St.ESPDrawings[p]=nil
            end
        end
    end

    if Cfg.Chams then
        for _, player in pairs(Players:GetPlayers()) do
            if player ~= lp and player.Character then
                if not St.ChamsHighlights[player] or not St.ChamsHighlights[player].Parent then
                    local hl=Instance.new("Highlight"); hl.Parent=player.Character; St.ChamsHighlights[player]=hl
                end
                local role=GetRole(player); local color=RoleColors[role] or Color3.fromRGB(255,255,255)
                St.ChamsHighlights[player].FillColor=color; St.ChamsHighlights[player].FillTransparency=0.5
                St.ChamsHighlights[player].OutlineColor=color; St.ChamsHighlights[player].OutlineTransparency=0
            end
        end
    end

    if Cfg.ItemESP then
        for _, obj in pairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") then
                local n=string.lower(obj.Name)
                if n:find("coin") or n:find("knife") or n:find("gun") or n:find("colt") or n:find("cash") or n:find("money") then
                    if not St.ItemESPGuis[obj] or not St.ItemESPGuis[obj].Parent then
                        local bb=Instance.new("BillboardGui"); bb.Size=UDim2.new(0,85,0,20); bb.AlwaysOnTop=true; bb.Parent=obj
                        local lbl=Instance.new("TextLabel"); lbl.Size=UDim2.new(1,0,1,0); lbl.BackgroundTransparency=1
                        lbl.Text=obj.Name; lbl.TextColor3=n:find("coin") and Color3.fromRGB(255,215,0) or Color3.fromRGB(255,80,80)
                        lbl.Font=Enum.Font.GothamBold; lbl.TextSize=9; lbl.Parent=bb; St.ItemESPGuis[obj]=bb
                    end
                end
            end
        end
    end
end)

-- Aim + AutoShoot + SpinBot + FakeLag
RunService.RenderStepped:Connect(function()
    local target=GetClosest()
    if (Cfg.AimBot or Cfg.SilentAim) and target and target.Character then
        local head=target.Character:FindFirstChild("Head")
        if head then Camera.CFrame=CFrame.new(Camera.CFrame.Position,head.Position) end
        if Cfg.AutoShoot then
            pcall(function()
                VirtualInputManager:SendMouseButtonEvent(0,0,0,true,game,0)
                VirtualInputManager:SendMouseButtonEvent(0,0,0,false,game,0)
            end)
        end
    end
end)

RunService.Heartbeat:Connect(function()
    if Cfg.SpinBot then
        local root=GetRoot(); if not root then return end
        if Cfg.SpinMode=="Full" then root.CFrame=root.CFrame*CFrame.Angles(0,math.rad(Cfg.SpinDegrees),0)
        elseif Cfg.SpinMode=="Jitter" then root.CFrame=root.CFrame*CFrame.Angles(math.rad(math.random(-90,90)),math.rad(math.random(-180,180)),math.rad(math.random(-90,90)))
        elseif Cfg.SpinMode=="Tilt" then root.CFrame=root.CFrame*CFrame.Angles(math.rad(Cfg.SpinDegrees),math.rad(Cfg.SpinDegrees*0.7),math.rad(Cfg.SpinDegrees*1.3)) end
    end

    if Cfg.FakeLag then
        local root=GetRoot(); if not root then return end
        St.chokeTimer=St.chokeTimer+1
        local maxTicks=Cfg.FakeLagMode=="Choke" and 5 or Cfg.FakeLagMode=="Burst" and 10 or math.clamp(math.floor(GetPing()/50),2,20)
        if St.chokeTimer>=maxTicks then
            if St.fakeLagBP then St.fakeLagBP:Destroy(); St.fakeLagBP=nil end; St.chokeTimer=0
        elseif not St.fakeLagBP then
            St.fakeLagBP=Instance.new("BodyPosition"); St.fakeLagBP.MaxForce=Vector3.new(math.huge,math.huge,math.huge)
            St.fakeLagBP.Position=root.Position; St.fakeLagBP.Parent=root
        end
    else
        if St.fakeLagBP then St.fakeLagBP:Destroy(); St.fakeLagBP=nil end; St.chokeTimer=0
    end
end)

-- GodMode + AutoDodge + Farm + Fling Protections
RunService.Heartbeat:Connect(function()
    local root=GetRoot()

    if Cfg.GodMode then local h=GetHum(); if h and h.Health<h.MaxHealth then h.Health=h.MaxHealth end end

    if Cfg.AutoDodge then
        if root then
            local hum=GetHum(); if hum and hum.Health>0 then
                local m=GetMurderer()
                if m and m.Character then
                    local mRoot=m.Character:FindFirstChild("HumanoidRootPart")
                    if mRoot then local dist=(mRoot.Position-root.Position).Magnitude; if dist<=12 then hum.Jump=true end end
                end
            end
        end
    end

    if not root then return end
    if root.Position.Y>0 then St.LastSafePosition=root.Position end

    if Cfg.AntiFling then
        for _,child in pairs(root:GetChildren()) do
            if child:IsA("BodyVelocity") or child:IsA("BodyAngularVelocity") or child:IsA("BodyThrust") or child:IsA("BodyForce") then child:Destroy() end
        end
    end
    if Cfg.VoidCatch and root.Position.Y<-50 then root.CFrame=CFrame.new(St.LastSafePosition) end
    if Cfg.AntiSpin then local bav=root:FindFirstChildOfClass("BodyAngularVelocity"); if bav then bav:Destroy() end end
    if Cfg.WeldDetector then
        for _,w in pairs(root:GetChildren()) do
            if (w:IsA("Weld") or w:IsA("WeldConstraint")) and w.Part0 and w.Part0~=root and w.Part0.Parent~=GetChar() then w:Destroy() end
        end
    end
    if Cfg.AntiRagdoll then
        local hum=GetHum()
        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Physics,false)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false)
            if hum:GetState()==Enum.HumanoidStateType.FallingDown or hum:GetState()==Enum.HumanoidStateType.Physics then
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end
        end
    end
end)

-- Farm loops
RunService.Heartbeat:Connect(function()
    local root=GetRoot(); if not root then return end
    if Cfg.AutoCoins then
        for _,obj in pairs(Workspace:GetDescendants()) do
            if obj:IsA("BasePart") then
                local n=string.lower(obj.Name)
                if n:find("coin") or n:find("cash") or n:find("money") then
                    if (obj.Position-root.Position).Magnitude<=8 then pcall(function() firetouchinterest(root,obj,0) end) end
                end
            end
        end
    end
    if Cfg.AutoWeapon then
        for _,obj in pairs(Workspace:GetDescendants()) do
            if obj:IsA("Tool") then
                local pos=obj:GetBoundingBox()
                if (pos.Position-root.Position).Magnitude<=15 then pcall(function() obj.Parent=lp.Backpack end) end
            elseif obj:IsA("BasePart") then
                local n=string.lower(obj.Name)
                if n:find("gun") or n:find("colt") or n:find("revolver") then
                    if (obj.Position-root.Position).Magnitude<=15 then pcall(function() firetouchinterest(root,obj,0) end) end
                end
            end
        end
    end
    if Cfg.AutoGun then
        for _,obj in pairs(Workspace:GetDescendants()) do
            if obj:IsA("Tool") then
                local n=string.lower(obj.Name)
                if n:find("gun") or n:find("colt") or n:find("revolver") or n:find("pistol") then
                    if not obj:FindFirstAncestorOfClass("Backpack") and not obj:FindFirstAncestorWhichIsA("Player") then
                        local handle=obj:FindFirstChild("Handle")
                        if handle and (handle.Position-root.Position).Magnitude<=50 then
                            pcall(function() firetouchinterest(root,handle,0) end)
                        end
                    end
                end
            end
        end
    end
end)

-- Anti AFK
lp.Idled:Connect(function()
    if Cfg.AntiAFK then pcall(function() VirtualUser:CaptureController(); VirtualUser:ClickButton2(Vector2.new()) end) end
end)

-- Alarm bar + watermark info
RunService.RenderStepped:Connect(function()
    St.FPSFrames=St.FPSFrames+1
    if tick()-St.LastFPSUpdate>=1 then
        St.FPSCounter=St.FPSFrames; St.FPSFrames=0; St.LastFPSUpdate=tick()
    end

    local root=GetRoot(); local murderer=GetMurderer()
    if root and murderer and murderer.Character then
        local mRoot=murderer.Character:FindFirstChild("HumanoidRootPart")
        if mRoot then
            local dist=(mRoot.Position-root.Position).Magnitude; local maxDist=60
            local pct=math.clamp(1-(dist/maxDist),0,1)
            alarmFill.Size=UDim2.new(pct,0,1,0)
            if dist<=maxDist then
                local v=math.floor(45+pct*210); alarmFill.BackgroundColor3=Color3.fromRGB(v,v,v)
                if dist<=15 then local pulse=(math.sin(tick()*8)+1)/2; alarmFill.BackgroundTransparency=0.2+pulse*0.3
                else alarmFill.BackgroundTransparency=0 end
                alarmText.Text="⚠ "..math.floor(dist).."s"; alarmText.TextColor3=Color3.fromRGB(235,235,238)
            else
                alarmFill.BackgroundColor3=Color3.fromRGB(45,45,50); alarmFill.BackgroundTransparency=0
                alarmText.Text="○ safe"; alarmText.TextColor3=Color3.fromRGB(160,160,165)
            end
        end
    else
        alarmFill.Size=UDim2.new(0,0,1,0); alarmFill.BackgroundColor3=Color3.fromRGB(45,45,50)
        alarmText.Text="○ safe"; alarmText.TextColor3=Color3.fromRGB(160,160,165)
    end

    -- Update Afraid Side watermark
    local role=GetRole(lp); local ping=GetPing()
    UI.setWatermark("MM2 Hub  |  "..tostring(St.FPSCounter).." fps  |  "..ping.." ms  |  "..role)
end)

-- ===================== INIT =====================
UISelectTab(tCombat, true)
UI.applyAppearance(true)
Assets.start()

task.spawn(function()
    local splash_obj = cfg.splash and UI.splash() or nil
    local waited = 0
    while not Assets.done and waited < 15 do task.wait(0.1); waited=waited+0.1 end
    refreshCfgList()
    local name = autoloadName()
    if name and cfgLoad(name,true) then notify("Autoloaded config: "..name, 2.5) end
    task.wait(0.35)
    if splash_obj then splash_obj.finish() end
    task.wait(0.35)
    UI.toggle(true)
    notify("MM2 Hub ready — "..cfg.menuKey.." toggles menu", 4)
end)

